# 百炼 SCRIPT：手卡意图解析 v2.9。入口 execute_intent_result。
# 禁止 _ 开头名字；不用 getattr。
# 上游「意图识别」LLM 输出 JSON；本节点解析 intent，并按步裁剪 candidates/dim_context 透传。
# 2.9.3：按 card_state 状态机硬纠正短确认（无目标→VISIT_GOAL；逐步确认跟 current_step）。


class CardIntentParse:
    def __init__(self, params):
        self.intent_obj = self.read(params, "intent_obj", "")
        self.user_input = self.read(params, "user_input", "")
        self.card_state = self.read(params, "card_state", {})
        self.metadata = self.read(params, "metadata", {})
        self.candidates = self.read(params, "candidates", "")
        self.goal_context = self.read(params, "goal_context", {})
        self.history_chats = self.read(params, "history_chats", "")

    def read(self, params, name, default):
        try:
            if name == "intent_obj":
                return params.intent_obj
            if name == "user_input":
                return params.user_input
            if name == "card_state":
                return params.card_state
            if name == "metadata":
                return params.metadata
            if name == "candidates":
                return params.candidates
            if name == "goal_context":
                return params.goal_context
            if name == "history_chats":
                return params.history_chats
        except Exception:
            return default
        return default

    def loads(self, value):
        if isinstance(value, dict) or isinstance(value, list):
            return value
        if value is None or value == "":
            return {}
        try:
            import json

            return json.loads(value)
        except Exception:
            return {}

    def dumps(self, value):
        if isinstance(value, str):
            return value
        try:
            import json

            return json.dumps(value, ensure_ascii=False)
        except Exception:
            return ""

    def as_dict(self, value):
        v = self.loads(value)
        if isinstance(v, dict):
            return v
        return {}

    def allowed(self):
        return (
            "VISIT_GOAL",
            "OPENING",
            "EXPLORE",
            "STRATEGY",
            "GENERATE_CARD",
            "CHITCHAT",
        )

    def text_has(self, text, keys):
        for key in keys:
            if key and key in text:
                return True
        return False

    def is_short_confirm(self, text):
        t = str(text or "").strip().lower()
        if not t:
            return False
        keys = [
            "可以",
            "行",
            "好的",
            "好",
            "嗯",
            "就用",
            "就按这个",
            "就按这个定",
            "定了",
            "确认",
            "没问题",
            "ok",
            "okay",
            "yes",
        ]
        # 过长不像短确认
        if len(t) > 20:
            return False
        for key in keys:
            if key in t:
                return True
        return False

    def is_chitchat_only(self, text):
        t = str(text or "").strip()
        if not t:
            return False
        biz = [
            "开场",
            "探寻",
            "策略",
            "手卡",
            "一键",
            "确认",
            "目标",
            "KM",
            "按步骤",
            "一项项",
            "生成",
            "可以",
            "定了",
            "就用",
            "换",
        ]
        if self.text_has(t, biz):
            return False
        chat = [
            "天气",
            "你好",
            "嗨",
            "在吗",
            "吃饭",
            "中午",
            "吃什么",
            "晚饭",
            "午饭",
            "明星",
            "热搜",
            "周末",
            "下班",
            "加班",
        ]
        return self.text_has(t, chat)

    def stepwise_intent_from_step(self, step):
        s = str(step or "").upper()
        if s == "EXPLORE":
            return "EXPLORE"
        if s in ("STRATEGY", "BARRIER", "INFO_MATERIAL"):
            return "STRATEGY"
        return "OPENING"

    def named_swap_intent(self, text):
        """点名换哪一栏；命中则返回 intent，否则空串。"""
        t = str(text or "")
        if self.text_has(
            t,
            [
                "换开场",
                "改开场",
                "换个开场",
                "换一个开场",
                "换开场话术",
                "改开场话术",
                "换一句开场",
                "换个方向",
                "换方向",
            ],
        ):
            return "OPENING"
        if self.text_has(
            t,
            [
                "换探寻",
                "改探寻",
                "换题",
                "换一个探寻",
                "换个探寻",
                "换一道",
                "换道题",
                "换一道题",
                "换个问题",
                "换一个问题",
            ],
        ):
            return "EXPLORE"
        if self.text_has(
            t,
            [
                "换策略",
                "改策略",
                "换沟通策略",
                "换个策略",
                "换一个策略",
                "换一条策略",
                "换材料",
                "换一页材料",
                "换页",
            ],
        ):
            return "STRATEGY"
        if self.text_has(t, ["换目标", "换KM", "换 KM", "改目标", "换一个KM", "换一条KM"]):
            return "VISIT_GOAL"
        return ""

    def is_bare_swap(self, text):
        """笼统「换一个」：未点名开场/探寻/策略。"""
        t = str(text or "").strip()
        if not t:
            return False
        if self.named_swap_intent(t):
            return False
        if len(t) > 24:
            return False
        bare = [
            "换一个",
            "换一个吧",
            "换一个呗",
            "换一句",
            "换一条",
            "换一下",
            "换个",
            "换一换",
            "再换一个",
            "换别的",
            "换其他",
            "不要这个",
            "不要这句",
            "不要这题",
            "不要这条",
            "换呗",
            "换咯",
        ]
        for key in bare:
            if key in t:
                return True
        # 极短「换」
        if t in ("换", "改", "重选", "重新"):
            return True
        return False

    def last_ai_text(self):
        """上一轮助手话术：用于笼统「换一个」锚定栏位。"""
        hist = str(self.history_chats or "")
        if hist:
            # 参数解析拼成的文本常含 assistant: ...
            marker = "assistant:"
            if marker in hist:
                return hist.rsplit(marker, 1)[-1].strip()
            return hist[-400:]
        md = self.as_dict(self.metadata)
        chats = md.get("chats") if isinstance(md.get("chats"), dict) else {}
        last = str(chats.get("last_ai_message") or "").strip()
        if last:
            return last
        return ""

    def infer_swap_from_ai(self, ai_text):
        """从上一轮 AI 正在确认的栏推断换什么。"""
        t = str(ai_text or "")
        # 后出现的栏优先（策略话术里也会提探寻）
        hits = []
        if self.text_has(t, ["开场话术", "确认本次拜访的开场", "推荐开场", "换开场", "开场（"]):
            hits.append(("OPENING", t.rfind("开场")))
        if self.text_has(t, ["探寻话术", "确认本次拜访的探寻", "探寻题", "换一道", "这道探寻"]):
            hits.append(("EXPLORE", max(t.rfind("探寻"), t.rfind("这道"))))
        if self.text_has(t, ["沟通策略", "确认本次拜访的沟通策略", "换策略", "这条策略"]):
            hits.append(("STRATEGY", max(t.rfind("策略"), t.rfind("沟通策略"))))
        if not hits:
            # 弱匹配
            if "开场" in t:
                hits.append(("OPENING", t.rfind("开场")))
            if "探寻" in t:
                hits.append(("EXPLORE", t.rfind("探寻")))
            if "策略" in t:
                hits.append(("STRATEGY", t.rfind("策略")))
        if not hits:
            return ""
        hits.sort(key=lambda x: x[1])
        return hits[-1][0]

    def resolve_swap_intent(self, cs):
        """换栏意图：点名 > current_step > 上一轮 AI 栏 > 默认开场。"""
        text = str(self.user_input or "")
        named = self.named_swap_intent(text)
        if named:
            return named, "点名改" + named
        step = str((cs or {}).get("current_step") or "").upper()
        mode = str((cs or {}).get("mode") or "").upper()
        status = str((cs or {}).get("final_status") or "").upper()
        if mode == "STEPWISE" and step in ("OPENING", "EXPLORE", "STRATEGY", "BARRIER", "INFO_MATERIAL"):
            intent = self.stepwise_intent_from_step(step)
            return intent, "笼统换一个→当前步 " + (step or "OPENING")
        ai_intent = self.infer_swap_from_ai(self.last_ai_text())
        if ai_intent:
            return ai_intent, "笼统换一个→上一轮AI栏 " + ai_intent
        if status == "READY_TO_CONFIRM" or mode == "ONE_CLICK":
            # 整卡待确认时笼统换：仍尽量跟 AI 摘要；否则默认开场（最常改）
            return "OPENING", "笼统换一个→整卡待确认默认开场"
        return "OPENING", "笼统换一个→默认开场"

    def fallback_intent(self, cs):
        target = str(cs.get("target_status") or "").upper()
        mode = str(cs.get("mode") or "").upper()
        step = str(cs.get("current_step") or "").upper()
        status = str(cs.get("final_status") or "").upper()
        if target != "CONFIRMED":
            return "VISIT_GOAL", "解析失败兜底：目标未确认"
        if self.is_bare_swap(self.user_input) or self.named_swap_intent(self.user_input):
            return self.resolve_swap_intent(cs)
        if status == "READY_TO_CONFIRM" or mode == "ONE_CLICK":
            return "GENERATE_CARD", "解析失败兜底：一键/待确认"
        if mode == "STEPWISE":
            intent = self.stepwise_intent_from_step(step)
            return intent, "解析失败兜底：逐步跟 current_step"
        # 目标已定待选模式
        return "GENERATE_CARD", "解析失败兜底：待选模式"

    def coerce_intent(self, intent, cs, reason):
        """状态机硬纠正：短确认跟当前步；无目标禁止一键。"""
        text = str(self.user_input or "").strip()
        target = str(cs.get("target_status") or "").upper()
        mode = str(cs.get("mode") or "").upper()
        step = str(cs.get("current_step") or "").upper()
        status = str(cs.get("final_status") or "").upper()
        reason = reason or ""

        # 点名 / 笼统换栏：优先于短确认与 LLM 误路由
        named = self.named_swap_intent(text)
        if named:
            return named, "点名改" + named
        if self.is_bare_swap(text):
            return self.resolve_swap_intent(cs)

        # 纯闲聊：逐步/待确认中也不跟 current_step 误绑
        if self.is_chitchat_only(text):
            return "CHITCHAT", "纯闲聊"

        # A. 目标未确认
        if target != "CONFIRMED":
            return "VISIT_GOAL", "目标未确认→先定拜访目标"

        # 确认生成
        if self.text_has(text, ["确认生成", "就这样生成", "就这样吧生成"]):
            return "GENERATE_CARD", "整卡确认生成"

        # 一键 / 逐步显式
        if self.text_has(text, ["一键生成", "一键出", "直接生成", "整张手卡", "整张草案"]):
            return "GENERATE_CARD", "用户要一键"
        if self.text_has(text, ["按步骤", "一项项", "一步步", "逐步"]):
            return "OPENING", "用户要按步骤→从开场开始"

        # B. 待选模式
        awaiting_mode = mode not in ("STEPWISE", "ONE_CLICK") and status != "READY_TO_CONFIRM"
        if awaiting_mode:
            if self.is_chitchat_only(text):
                return "CHITCHAT", "待选模式闲聊"
            # 短确认/未表态：走 GENERATE_CARD，由专精/脚本短问模式
            return "GENERATE_CARD", "目标已定待选模式"

        # C. 逐步：短确认跟 current_step（本步确认，脚本再推进）
        if mode == "STEPWISE" and status != "READY_TO_CONFIRM":
            if self.is_short_confirm(text) or not intent:
                nxt = self.stepwise_intent_from_step(step)
                return nxt, "逐步短确认→当前步 " + (step or "OPENING")
            # LLM 在逐步中乱跳到 GENERATE_CARD：拉回当前步
            if intent == "GENERATE_CARD" and not self.text_has(text, ["确认生成", "一键"]):
                nxt = self.stepwise_intent_from_step(step)
                return nxt, "逐步中纠正误路由 GENERATE_CARD"

        # D. READY / ONE_CLICK：短确认 → 确认生成
        if status == "READY_TO_CONFIRM" or mode == "ONE_CLICK":
            if self.is_short_confirm(text) and not self.text_has(
                text, ["换", "改", "探寻", "开场", "策略", "目标"]
            ):
                return "GENERATE_CARD", "整卡待确认短确认→确认生成"

        return intent, reason

    def gate_intent(self, intent, cs, reason):
        """目标未确认时禁止 GENERATE_CARD。"""
        target = str(cs.get("target_status") or "").upper()
        if intent == "GENERATE_CARD" and target != "CONFIRMED":
            return "VISIT_GOAL", "一键前先确认拜访目标"
        return intent, reason

    def unwrap(self, value):
        for step in range(10):
            if isinstance(value, dict):
                if "intent" in value:
                    return value
                found = False
                for key in ("current", "content", "text"):
                    if key in value:
                        value = value[key]
                        found = True
                        break
                if found:
                    continue
                return None
            if not isinstance(value, str):
                return None
            text = value.strip().lstrip("\ufeff").strip()
            if not text:
                return None
            if text.startswith("```"):
                text = text[3:].strip()
                if text[:4].lower() == "json":
                    text = text[4:].lstrip()
                if text.endswith("```"):
                    text = text[:-3].rstrip()
            upper = text.upper()
            if upper in self.allowed():
                return {"intent": upper, "reason": ""}
            # CARD / OTHER 兼容主侧旧枚举
            if upper == "CARD":
                return {"intent": "GENERATE_CARD", "reason": "兼容 CARD"}
            if upper == "OTHER":
                return {"intent": "CHITCHAT", "reason": "兼容 OTHER"}
            decoded = self.decode_text(text)
            if decoded is None:
                return None
            value = decoded
        return None

    def decode_text(self, text):
        try:
            import json

            return json.loads(text)
        except Exception:
            pass
        candidate = text
        if text.startswith('"intent"') or text.startswith('"reason"'):
            candidate = "{" + text
        if candidate.startswith("{") and not candidate.endswith("}"):
            candidate = candidate + "}"
        if candidate != text:
            try:
                import json

                return json.loads(candidate)
            except Exception:
                pass
        try:
            import json

            decoder = json.JSONDecoder()
            found = None
            position = 0
            while position < len(text):
                start = text.find("{", position)
                if start < 0:
                    break
                try:
                    obj, end = decoder.raw_decode(text, start)
                except Exception:
                    position = start + 1
                    continue
                position = end
                if not isinstance(obj, dict):
                    continue
                hit = False
                for key in ("intent", "current", "content", "text"):
                    if key in obj:
                        hit = True
                        break
                if hit:
                    if found is not None:
                        return None
                    found = obj
            return found
        except Exception:
            return None

    def normalize_intent(self, raw):
        if not isinstance(raw, str):
            return ""
        intent = raw.strip().upper()
        if intent == "CARD":
            return "GENERATE_CARD"
        if intent == "OTHER":
            return "CHITCHAT"
        if intent in self.allowed():
            return intent
        return ""

    def pick_step_candidates(self, cand, intent):
        root = self.as_dict(cand)
        steps = root.get("step_candidates")
        if not isinstance(steps, dict):
            steps = root if isinstance(root, dict) else {}
        mapping = {
            "VISIT_GOAL": ["VISIT_GOAL", "KM"],
            "OPENING": ["OPENING"],
            "EXPLORE": ["EXPLORE"],
            "STRATEGY": ["STRATEGY"],
            "GENERATE_CARD": [
                "VISIT_GOAL",
                "OPENING",
                "EXPLORE",
                "BARRIER",
                "INFO_MATERIAL",
                "STRATEGY",
                "KM",
            ],
            "CHITCHAT": [],
        }
        keys = mapping.get(intent) or []
        if intent == "CHITCHAT":
            return {}
        if intent == "GENERATE_CARD" or not keys:
            if isinstance(steps, dict) and steps:
                return {"step_candidates": steps}
            return root
        narrowed = {}
        for k in keys:
            if k in steps:
                narrowed[k] = steps.get(k)
        if intent in ("OPENING", "EXPLORE", "STRATEGY") and "VISIT_GOAL" in steps:
            narrowed["VISIT_GOAL"] = steps.get("VISIT_GOAL")
        if not narrowed:
            return root
        return {"step_candidates": narrowed}

    def build_dim_context(self, intent, cs, goal, cand_narrow):
        g = self.as_dict(goal)
        visit = cs.get("visit_goal") if isinstance(cs.get("visit_goal"), dict) else {}
        steps = cs.get("steps") if isinstance(cs.get("steps"), dict) else {}
        opening = steps.get("opening") if isinstance(steps.get("opening"), dict) else {}
        explore = steps.get("explore") if isinstance(steps.get("explore"), dict) else {}
        barrier = steps.get("barrier") if isinstance(steps.get("barrier"), dict) else {}
        info_material = steps.get("info_material") if isinstance(steps.get("info_material"), dict) else {}
        strategy = steps.get("strategy") if isinstance(steps.get("strategy"), dict) else {}

        cs_code = g.get("cs_code") or g.get("csCode") or visit.get("concept_code") or ""
        cs_name = g.get("cs_name") or g.get("csName") or ""
        cs_desc = g.get("cs_desc") or g.get("csDesc") or ""
        cs_goal = g.get("cs_goal") or g.get("csGoal") or visit.get("concept_text") or ""
        indication = g.get("indication_code") or g.get("indicationCode") or ""

        objection_id = (
            g.get("objection_id")
            or visit.get("objection_id")
            or barrier.get("objection_id")
            or g.get("barrier_id")
            or visit.get("barrier_id")
            or ""
        )
        objection_name = (
            g.get("objection_name")
            or visit.get("objection_name")
            or barrier.get("objection_name")
            or g.get("barrier_name")
            or visit.get("barrier_name")
            or ""
        )
        objection_source = (
            g.get("objection_source")
            or visit.get("objection_source")
            or barrier.get("objection_source")
            or ""
        )
        evidence = g.get("evidence") or barrier.get("evidence") or visit.get("objection_text") or ""

        km_ids = visit.get("km_ids") or g.get("recommend_km_ids") or []
        km_items = visit.get("km_items") or g.get("km_items") or []

        dim = {
            "intent": intent,
            "cs": {
                "csCode": cs_code,
                "csName": cs_name,
                "csDesc": cs_desc,
                "csGoal": cs_goal,
                "indicationCode": indication,
            },
            "objection": {
                "objectionCode": objection_id,
                "objectionDesc": objection_name,
                "objectionSource": objection_source,
                "evidence": evidence,
            },
            "barrier": {
                "barrierCode": visit.get("barrier_id") or g.get("barrier_id") or "",
                "barrierName": visit.get("barrier_name") or g.get("barrier_name") or "",
            },
            "visit_goal": {
                "status": visit.get("status") or cs.get("target_status") or "",
                "goal_type": visit.get("goal_type") or "",
                "text": visit.get("text") or g.get("visit_goal_text") or "",
                "km_ids": km_ids,
                "km_items": km_items,
                "recommend_km_ids": visit.get("recommend_km_ids") or g.get("recommend_km_ids") or [],
            },
            "selected": {
                "opening_id": opening.get("opening_id") or "",
                "opening_text": opening.get("text") or "",
                "question_ids": explore.get("question_ids") or [],
                "questions": explore.get("questions") or [],
                "strategy_code": strategy.get("strategy_code") or "",
                "strategy_name": strategy.get("strategy_name") or "",
                "strategy_desc": strategy.get("strategy_desc") or "",
                "material_pages": info_material.get("selected_pages") or [],
                "material_names": info_material.get("material_names") or [],
            },
            "step_candidates": self.as_dict(cand_narrow).get("step_candidates") or cand_narrow,
        }

        if intent == "CHITCHAT":
            return {
                "intent": intent,
                "cs": {"csCode": cs_code},
                "visit_goal": {"status": dim["visit_goal"]["status"]},
            }
        if intent == "VISIT_GOAL":
            dim.pop("selected", None)
        if intent == "OPENING":
            if isinstance(dim.get("step_candidates"), dict):
                keep = {}
                for k in ("OPENING", "VISIT_GOAL"):
                    if k in dim["step_candidates"]:
                        keep[k] = dim["step_candidates"][k]
                dim["step_candidates"] = keep
        if intent == "EXPLORE":
            if isinstance(dim.get("step_candidates"), dict):
                keep = {}
                for k in ("EXPLORE", "VISIT_GOAL"):
                    if k in dim["step_candidates"]:
                        keep[k] = dim["step_candidates"][k]
                dim["step_candidates"] = keep
            dim["barrier"] = {"barrierCode": "", "barrierName": ""}
        if intent == "STRATEGY":
            if isinstance(dim.get("step_candidates"), dict):
                keep = {}
                for k in ("STRATEGY", "VISIT_GOAL"):
                    if k in dim["step_candidates"]:
                        keep[k] = dim["step_candidates"][k]
                dim["step_candidates"] = keep
        if intent == "GENERATE_CARD":
            pages = info_material.get("selected_pages") or []
            dim["materials"] = pages
        return dim

    def build_result(self):
        cs = self.loads(self.card_state)
        if not isinstance(cs, dict):
            cs = {}

        parse_ok = False
        error = ""
        intent = ""
        reason = ""
        data = self.unwrap(self.intent_obj)
        if isinstance(data, dict):
            intent = self.normalize_intent(data.get("intent"))
            reason_raw = data.get("reason", "")
            if reason_raw is None:
                reason_raw = ""
            if isinstance(reason_raw, str):
                reason = reason_raw.strip()
            else:
                reason = ""
                error = "reason 必须是字符串"
            if intent:
                parse_ok = True
            else:
                error = "intent 非法或缺失"
        else:
            error = "无法解析意图识别 LLM 输出"

        if not intent:
            intent, fb_reason = self.fallback_intent(cs)
            if not reason:
                reason = fb_reason

        intent, reason = self.gate_intent(intent, cs, reason)
        intent, reason = self.coerce_intent(intent, cs, reason)
        intent, reason = self.gate_intent(intent, cs, reason)

        cs["route_intent"] = intent
        cs["route_reason"] = reason
        cs["route_parse_ok"] = parse_ok

        cand_narrow = self.pick_step_candidates(self.candidates, intent)
        dim_context = self.build_dim_context(intent, cs, self.goal_context, cand_narrow)

        goal_out = self.goal_context
        hist_out = self.history_chats
        if intent == "CHITCHAT":
            goal_out = {}
            cand_narrow = {}
        if intent == "EXPLORE":
            g = self.as_dict(self.goal_context)
            goal_out = {
                "cs_code": g.get("cs_code") or g.get("csCode") or "",
                "objection_id": g.get("objection_id") or "",
                "objection_name": g.get("objection_name") or "",
                "visit_goal_text": g.get("visit_goal_text") or "",
                "recommend_km_ids": g.get("recommend_km_ids") or [],
            }

        return {
            "intent": intent,
            "reason": reason,
            "parse_ok": parse_ok,
            "error": error,
            "user_input": self.user_input,
            "card_state": cs,
            "candidates": cand_narrow if isinstance(cand_narrow, str) else self.dumps(cand_narrow),
            "goal_context": goal_out if isinstance(goal_out, str) else self.dumps(goal_out),
            "dim_context": self.dumps(dim_context),
            "metadata": self.metadata,
            "history_chats": hist_out,
        }


