# 百炼 SCRIPT：六路专精 LLM 汇合归一 v2.9。入口 execute_coalesce_result。
# 禁止 _ 开头名字；不用 getattr。
# 硬规则：本节点只绑定六路 LLM 的 content（直连上游），禁止再绑网关前的参数解析/意图节点。
# 2.9：互斥网关只跑一路，但空壳 "{}" / 脏残留可能占坑；按「含 reply 的真实 JSON」打分选取，闲聊不再被前面空壳抢走。


class CardCoalesce:
    def __init__(self, params):
        self.content_visit_goal = self.read(params, "content_visit_goal", "")
        self.content_opening = self.read(params, "content_opening", "")
        self.content_explore = self.read(params, "content_explore", "")
        self.content_strategy = self.read(params, "content_strategy", "")
        self.content_generate = self.read(params, "content_generate", "")
        self.content_chitchat = self.read(params, "content_chitchat", "")
        self.intent = self.read(params, "intent", "")
        self.user_input = self.read(params, "user_input", "")
        self.card_state = self.read(params, "card_state", {})
        self.candidates = self.read(params, "candidates", "")
        self.goal_context = self.read(params, "goal_context", {})
        self.metadata = self.read(params, "metadata", {})
        self.history_chats = self.read(params, "history_chats", "")

    def read(self, params, name, default):
        try:
            if name == "content_visit_goal":
                return params.content_visit_goal
            if name == "content_opening":
                return params.content_opening
            if name == "content_explore":
                return params.content_explore
            if name == "content_strategy":
                return params.content_strategy
            if name == "content_generate":
                return params.content_generate
            if name == "content_chitchat":
                return params.content_chitchat
            if name == "intent":
                return params.intent
            if name == "user_input":
                return params.user_input
            if name == "card_state":
                return params.card_state
            if name == "candidates":
                return params.candidates
            if name == "goal_context":
                return params.goal_context
            if name == "metadata":
                return params.metadata
            if name == "history_chats":
                return params.history_chats
        except Exception:
            return default
        return default

    def as_text(self, value):
        if value is None:
            return ""
        if isinstance(value, dict) or isinstance(value, list):
            try:
                import json

                return json.dumps(value, ensure_ascii=False)
            except Exception:
                return str(value)
        return str(value)

    def try_parse(self, text):
        if not isinstance(text, str):
            return None
        raw = text.strip()
        if not raw or raw in ("{}", "[]", "null", "None", '""'):
            return None
        if raw.startswith("```"):
            raw = raw[3:].strip()
            if raw[:4].lower() == "json":
                raw = raw[4:].lstrip()
            if raw.endswith("```"):
                raw = raw[:-3].rstrip()
        try:
            import json

            obj = json.loads(raw)
            if isinstance(obj, dict):
                return obj
        except Exception:
            return None
        return None

    def score_content(self, value, branch_name):
        text = self.as_text(value).strip()
        if not text or text in ("{}", "[]", "null", "None"):
            return 0, text
        obj = self.try_parse(text)
        score = 1
        if obj is None:
            # 非 JSON 但有正文：弱候选
            if len(text) > 8:
                return 2, text
            return 0, text
        reply = obj.get("reply")
        if isinstance(reply, str) and reply.strip():
            score = 10 + min(len(reply.strip()), 200) // 20
        rt = str(obj.get("reply_type") or "").upper()
        action = str(obj.get("action") or "").upper()
        if rt in ("STEP", "CHITCHAT", "FINAL_CONFIRM", "DONE", "SUMMARY"):
            score = score + 5
        if action in ("ADVANCE", "STAY", "FALLBACK", "FINISH", "PRESENT_SUMMARY"):
            score = score + 2
        # 闲聊专精：明确 CHITCHAT/FALLBACK 再加分，避免被空壳 STEP 抢
        if branch_name == "chitchat" and (rt == "CHITCHAT" or action == "FALLBACK"):
            score = score + 8
        if branch_name == "chitchat" and reply and "插不上话" in str(reply):
            score = score + 3
        return score, text

    def pick_content(self):
        branches = [
            ("visit_goal", self.content_visit_goal),
            ("opening", self.content_opening),
            ("explore", self.content_explore),
            ("strategy", self.content_strategy),
            ("generate", self.content_generate),
            ("chitchat", self.content_chitchat),
        ]
        # 意图已是闲聊：优先吃闲聊专精，避免空壳 STEP 抢占
        if str(self.intent or "").upper() == "CHITCHAT":
            score, text = self.score_content(self.content_chitchat, "chitchat")
            if score > 0 and text:
                return text
        best_score = 0
        best_text = ""
        for name, value in branches:
            score, text = self.score_content(value, name)
            if score > best_score:
                best_score = score
                best_text = text
        if best_text:
            return best_text
        return "{}"

    def build_result(self):
        return {
            "intent": str(self.intent or ""),
            "llm_raw": self.pick_content(),
            "user_input": self.user_input,
            "card_state": self.card_state,
            "candidates": self.candidates,
            "goal_context": self.goal_context,
            "metadata": self.metadata,
            "history_chats": self.history_chats,
        }


def execute_coalesce_result(params):
    return CardCoalesce(params).build_result()

# 百炼 SCRIPT：规范手卡结果 v2.11。入口 execute_card_llm_result。
# 五步 OPENING→EXPLORE→BARRIER→INFO_MATERIAL→STRATEGY；整卡确认写 state.final_card。
# 契约：LLM 出编号；本脚本把编号解析成全文写入 card_state；reply 只给人看话术。
# 2.11：开场按近期动态有无数据优选；探寻按 CS；话术偏沟通引导（有 sense），不像做题。
# 2.10：沟通材料=策略子选项（strategy.pages）；选定/更换策略时同步材料页。
# 2.10：拜访目标/开场话术确认后仍可随时「换目标/换开场」（READY 或逐步中均可）。
# 2.9 基线：改探寻/闲聊保留专精 reply；一键空壳补文案；目标门禁；闲聊 unrelated_count+1；异议正文展示。

STEP_ORDER = ["OPENING", "EXPLORE", "BARRIER", "INFO_MATERIAL", "STRATEGY"]
STEP_KEY = {
    "OPENING": "opening",
    "EXPLORE": "explore",
    "BARRIER": "barrier",
    "INFO_MATERIAL": "info_material",
