class CardResultFormatter:
    def __init__(self, params):
        self.llm_raw = params.llm_raw
        self.card_state = params.card_state
        self.candidates = params.candidates
        self.goal_context = params.goal_context
        self.metadata = params.metadata
        self.user_input = params.user_input
        # 上游意图识别 / 汇合透传；闲聊计数用
        try:
            self.intent = params.intent
        except Exception:
            self.intent = ""

    def loads(self, value):
        if isinstance(value, dict) or isinstance(value, list):
            return value
        if not isinstance(value, str):
            return value
        text = value.strip()
        if not text:
            return {}
        try:
            import json

            return json.loads(text)
        except ValueError:
            return {}

    def parse_llm(self, value):
        import json
        import re

        for step in range(8):
            if isinstance(value, dict):
                if "reply" in value or "reply_type" in value or "action" in value:
                    return value
                wrapped = None
                for key in ("current", "text", "content", "result", "output", "data"):
                    if key in value:
                        if isinstance(value[key], str) or isinstance(value[key], dict):
                            wrapped = value[key]
                            break
                if wrapped is None:
                    raise ValueError("模型结果缺少 reply/action")
                value = wrapped
                continue
            if not isinstance(value, str):
                raise ValueError("llm_raw 必须是字典或 JSON 字符串")
            content = value.strip()
            block = re.search(r"```(?:json)?\s*(.*?)\s*```", content, re.I | re.S)
            if block:
                content = block.group(1)
            variants = [content, re.sub(r",\s*([}\]])", r"\1", content)]
            parsed = None
            for variant in variants:
                try:
                    parsed = json.loads(variant)
                    break
                except ValueError:
                    continue
            if parsed is None:
                variant = re.sub(r"(?<!\\)'([^'\\]*(?:\\.[^'\\]*)*)'", r'"\1"', variants[1])
                variant = re.sub(r"\bNone\b", "null", variant)
                variant = re.sub(r"\bTrue\b", "true", variant)
                variant = re.sub(r"\bFalse\b", "false", variant)
                variants.append(variant)
                for candidate in variants:
                    for pos in range(len(candidate)):
                        if candidate[pos] != "{":
                            continue
                        try:
                            object_value, end = json.JSONDecoder().raw_decode(candidate[pos:])
                            if isinstance(object_value, dict):
                                parsed = object_value
                                break
                        except ValueError:
                            continue
                    if parsed is not None:
                        break
            if parsed is None:
                raise ValueError("无法解析模型 JSON")
            value = parsed
        raise ValueError("模型结果嵌套层数过多")

    def candidate_ids(self, step_name):
        data = self.candidates_obj()
        steps = data.get("step_candidates") or {}
        block = steps.get(step_name) or {}
        if not isinstance(block, dict):
            block = {}
        ids = []
        if step_name == "OPENING":
            for item in block.get("items") or []:
                if isinstance(item, dict):
                    ids.append(str(item.get("id")))
        elif step_name == "EXPLORE":
            for item in block.get("items") or []:
                if isinstance(item, dict):
                    ids.append(str(item.get("id")))
        elif step_name == "BARRIER":
            # 只读展示：id 来自 filter_context / block
            oid = block.get("objection_id") or ""
            if oid:
                ids.append(str(oid))
        elif step_name == "INFO_MATERIAL":
            for item in block.get("pages") or []:
                if not isinstance(item, dict):
                    continue
                mid = item.get("material_name") or item.get("page")
                if mid:
                    ids.append(str(mid))
            for item in block.get("km_pages_supplement") or []:
                if not isinstance(item, dict):
                    continue
                kid = item.get("km_id")
                if kid:
                    ids.append(str(kid))
            for item in block.get("materials") or []:
                if not isinstance(item, dict):
                    continue
                mid = item.get("material_id") or item.get("approval_no") or item.get("name")
                if mid:
                    ids.append(str(mid))
        elif step_name == "STRATEGY":
            for item in block.get("items") or []:
                if isinstance(item, dict):
                    ids.append(str(item.get("strategy_code")))
        return ids

    def count_confirmed(self, card_state):
        done = 0
        steps = card_state.get("steps") or {}
        for key in ("opening", "explore", "barrier", "info_material", "strategy"):
            item = steps.get(key) or {}
            if str(item.get("status") or "").upper() == "CONFIRMED":
                done += 1
        return done

    def visit_goal_text(self, card_state, goal_context):
        vg = card_state.get("visit_goal") if isinstance(card_state, dict) else None
        if isinstance(vg, dict) and vg.get("text"):
            return str(vg.get("text"))
        if isinstance(goal_context, dict):
            g = goal_context.get("visit_goal")
            if isinstance(g, dict) and g.get("text"):
                return str(g.get("text"))
            if goal_context.get("visit_goal_text"):
                return str(goal_context.get("visit_goal_text"))
            if isinstance(g, str):
                return g
        return ""

    def refresh_visit_goal_from_km(self, visit_goal, goal_context):
        """拜访目标 = 选定 KM；异议只填充不改。按 KM 重写 text / km_items。"""
        vg = dict(visit_goal or {})
        g = goal_context or {}
        km_ids = []
        raw_ids = vg.get("km_ids") or g.get("target_km_ids") or []
        if isinstance(raw_ids, list):
            for x in raw_ids:
                if x and str(x) not in km_ids:
                    km_ids.append(str(x))
        km_items = self.lookup_kms(km_ids) if km_ids else []
        # 异议只读填充
        objection_id = (
            vg.get("objection_id")
            or vg.get("barrier_id")
            or g.get("objection_id")
            or g.get("barrier_id")
            or ""
        )
        objection_name = (
            vg.get("objection_name")
            or vg.get("barrier_name")
            or g.get("objection_name")
            or g.get("barrier_name")
            or ""
        )
        objection_text = vg.get("objection_text") or g.get("objection_evidence") or ""
        if objection_id:
            vg["objection_id"] = str(objection_id)
            vg["barrier_id"] = str(objection_id)
        if objection_name:
            vg["objection_name"] = str(objection_name)
            vg["barrier_name"] = str(objection_name)
        if objection_text and not vg.get("objection_text"):
            vg["objection_text"] = str(objection_text)

        goal_type = str(vg.get("goal_type") or "").upper()
        has_objection = bool(objection_id) and str(objection_id) != "B009"
        if not goal_type:
            goal_type = "OBJECTION_CLEAR" if has_objection else "CONCEPT_BUILD"
        km_label = km_ids[0] if km_ids else "KM"
        km_text = (km_items[0].get("km_name") if km_items else "") or km_label
        if goal_type == "OBJECTION_CLEAR" and has_objection:
            obj_label = objection_name or objection_id
            vg["text"] = "通过传递「" + km_text + "」，解决客户关于「" + obj_label + "」的异议"
            vg["goal_type"] = "OBJECTION_CLEAR"
        else:
            concept_text = vg.get("concept_text") or g.get("concept_text") or "本次需建立的关键观念"
            vg["concept_text"] = str(concept_text)
            vg["text"] = "通过传递「" + km_text + "」，建立客户关于「" + concept_text + "」的观念"
            vg["goal_type"] = "CONCEPT_BUILD"
        vg["km_ids"] = km_ids
        vg["km_items"] = km_items
        return vg

    def seed_km_step_from_goal(self, card_state):
        """目标确认后：预填障碍步只读字段（仍待本步确认）；KM 留在 visit_goal。"""
        steps = card_state.get("steps")
        if not isinstance(steps, dict):
            steps = {}
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        barrier = steps.get("barrier")
        if not isinstance(barrier, dict):
            barrier = {
                "status": "PENDING",
                "objection_source": "",
                "objection_id": "",
                "objection_name": "",
                "evidence": "",
            }
        if not barrier.get("objection_id"):
            barrier["objection_source"] = vg.get("objection_source") or ""
            barrier["objection_id"] = vg.get("objection_id") or vg.get("barrier_id") or ""
            barrier["objection_name"] = vg.get("objection_name") or vg.get("barrier_name") or ""
            barrier["evidence"] = vg.get("objection_text") or ""
        if str(barrier.get("status") or "").upper() not in ("PENDING", "CONFIRMED"):
            barrier["status"] = "PENDING"
        steps["barrier"] = barrier
        card_state["steps"] = steps
        return card_state

    def candidates_obj(self):
        c = self.candidates
        if isinstance(c, str):
            c = self.loads(c)
        if not isinstance(c, dict):
            return {}
        return c

    def lookup_opening(self, opening_id):
        block = (self.candidates_obj().get("step_candidates") or {}).get("OPENING") or {}
        for item in block.get("items") or []:
            if str(item.get("id") or "") == str(opening_id):
                return item
        return {}

    def lookup_questions(self, question_ids):
        block = (self.candidates_obj().get("step_candidates") or {}).get("EXPLORE") or {}
        found = []
        for qid in question_ids or []:
            hit = None
            for item in block.get("items") or []:
                if str(item.get("id") or "") == str(qid):
                    hit = item
                    break
            if hit:
                found.append({"id": str(qid), "text": str(hit.get("text") or "")})
            else:
                found.append({"id": str(qid), "text": ""})
        return found

    def lookup_kms(self, km_ids):
        visit = (self.candidates_obj().get("step_candidates") or {}).get("VISIT_GOAL") or {}
        info = (self.candidates_obj().get("step_candidates") or {}).get("INFO_MATERIAL") or {}
        name_map = {}
        for item in visit.get("recommend_kms") or []:
            name_map[str(item.get("km_id") or "")] = str(item.get("km_name") or "")
        for item in info.get("km_pages_supplement") or info.get("km_pages") or []:
            kid = str(item.get("km_id") or "")
            if kid and kid not in name_map:
                name_map[kid] = str(item.get("km_name") or "")
        out = []
        for kid in km_ids or []:
            out.append({"km_id": str(kid), "km_name": name_map.get(str(kid), "")})
        return out

    def lookup_strategy(self, code):
        block = (self.candidates_obj().get("step_candidates") or {}).get("STRATEGY") or {}
        for item in block.get("items") or []:
            if str(item.get("strategy_code") or "") == str(code):
                return item
        return {}

    def next_step(self, step_name):
        """用户逐步确认路径：开场→探寻→策略（障碍/材料自动落库，跳过问答）。"""
        if step_name is None:
            return "OPENING"
        name = str(step_name or "").upper()
        if name == "OPENING":
            return "EXPLORE"
        if name == "EXPLORE":
            return "STRATEGY"
        if name in ("BARRIER", "INFO_MATERIAL"):
            return "STRATEGY"
        if name == "STRATEGY":
            return None
        for idx in range(len(STEP_ORDER)):
            if STEP_ORDER[idx] == name:
                if idx + 1 < len(STEP_ORDER):
                    return STEP_ORDER[idx + 1]
                return None
        return "OPENING"

    def auto_confirm_linked_steps(self, card_state):
        """障碍=异议只读；材料优先挂当前策略 pages 子选项，自动 CONFIRMED。"""
        card_state = self.ensure_visit_goal_km_names(card_state)
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        steps = card_state.get("steps")
        if not isinstance(steps, dict):
            steps = {}

        barrier = dict(steps.get("barrier") or {})
        barrier["objection_id"] = (
            barrier.get("objection_id")
            or vg.get("objection_id")
            or vg.get("barrier_id")
            or ""
        )
        barrier["objection_source"] = (
            barrier.get("objection_source")
            or vg.get("objection_source")
            or "BARRIER"
        )
        barrier["objection_name"] = (
            barrier.get("objection_name")
            or vg.get("objection_name")
            or vg.get("barrier_name")
            or ""
        )
        barrier["evidence"] = (
            barrier.get("evidence")
            or vg.get("objection_text")
            or ""
        )
        # 无异议时也 CONFIRMED 空壳，避免卡 FINISH
        barrier["status"] = "CONFIRMED"
        steps["barrier"] = barrier
        card_state["steps"] = steps

        # 2.10：材料=策略子选项；有策略码则强制按 strategy.pages 同步
        card_state = self.sync_materials_from_strategy(card_state, force=False)
        steps = card_state.get("steps") if isinstance(card_state.get("steps"), dict) else {}
        material = dict(steps.get("info_material") or {})
        has_pages = bool(material.get("selected_pages") or material.get("material_names"))
        if not has_pages:
            material = self.recommended_material_confirm(card_state)
        material["km_ids"] = list(material.get("km_ids") or vg.get("km_ids") or [])
        material["status"] = "CONFIRMED"
        steps["info_material"] = material
        card_state["steps"] = steps
        return self.resolve_known_step_texts(card_state)

    def validate_step_result(self, step_name, result):
        if not isinstance(result, dict):
            raise ValueError("step_result 必须是对象")
        ids = self.candidate_ids(step_name)
        status = str(result.get("status") or "PENDING").upper()
        if status not in ("PENDING", "CONFIRMED"):
            raise ValueError("step_result.status 无效")

        if step_name == "OPENING":
            opening_id = str(result.get("opening_id") or result.get("selected_id") or "")
            if opening_id and ids and opening_id not in ids:
                raise ValueError("开场 id 不在候选：" + opening_id)
            hit = self.lookup_opening(opening_id) if opening_id else {}
            direction_code = str(
                result.get("direction_code") or result.get("direction") or hit.get("direction") or ""
            )
            if opening_id and len(opening_id) >= 2 and not direction_code:
                direction_code = opening_id[:2]
            return {
                "status": status,
                "opening_id": opening_id,
                "direction_code": direction_code,
                "direction_name": str(
                    result.get("direction_name") or hit.get("direction_name") or ""
                ),
                "text": str(result.get("text") or hit.get("text") or ""),
            }

        if step_name == "EXPLORE":
            selected_ids = result.get("question_ids") or result.get("selected_ids") or []
            if not isinstance(selected_ids, list):
                raise ValueError("question_ids 必须是列表")
            clean = []
            for item in selected_ids:
                sid = str(item)
                if ids and sid not in ids:
                    raise ValueError("探寻 id 不在候选：" + sid)
                if sid and sid not in clean:
                    clean.append(sid)
            questions = result.get("questions") or []
            if not isinstance(questions, list) or not questions:
                questions = self.explore_questions_or_fallback(clean)
            else:
                # 有 id 无 text 时仍兜底补齐
                filled = self.explore_questions_or_fallback(clean)
                by_id = {}
                for q in filled:
                    if isinstance(q, dict) and q.get("id"):
                        by_id[str(q.get("id"))] = q
                merged_q = []
                for q in questions:
                    if not isinstance(q, dict):
                        continue
                    qid = str(q.get("id") or "")
                    text = str(q.get("text") or "").strip()
                    if not text and qid in by_id:
                        merged_q.append(dict(by_id[qid]))
                    else:
                        merged_q.append({"id": qid, "text": text or str(q.get("text") or "")})
                if not merged_q:
                    merged_q = filled
                questions = merged_q
            return {
                "status": status,
                "question_ids": clean,
                "questions": questions,
                "note": str(result.get("note") or ""),
            }

        if step_name == "BARRIER":
            # 只读落库 visit_goal 异议；忽略 LLM 改判
            cs = self.loads(self.card_state)
            vg = (cs or {}).get("visit_goal") if isinstance(cs, dict) else {}
            if not isinstance(vg, dict):
                vg = {}
            g = self.loads(self.goal_context)
            if not isinstance(g, dict):
                g = {}
            oid = str(
                vg.get("objection_id")
                or vg.get("barrier_id")
                or g.get("objection_id")
                or g.get("barrier_id")
                or result.get("objection_id")
                or ""
            )
            source = str(
                vg.get("objection_source")
                or g.get("objection_source")
                or result.get("objection_source")
                or ""
            )
            oname = str(
                vg.get("objection_name")
                or vg.get("barrier_name")
                or g.get("objection_name")
                or result.get("objection_name")
                or ""
            )
            evidence = str(
                vg.get("objection_text")
                or g.get("objection_evidence")
                or result.get("evidence")
                or ""
            )
            return {
                "status": status,
                "objection_source": source,
                "objection_id": oid,
                "objection_name": oname,
                "evidence": evidence,
            }

        if step_name == "INFO_MATERIAL":
            km_ids = result.get("km_ids") or []
            material_ids = result.get("material_ids") or []
            pages = result.get("selected_pages") or []
            if not isinstance(km_ids, list) or not isinstance(material_ids, list) or not isinstance(pages, list):
                raise ValueError("INFO_MATERIAL 字段类型错误")
            clean_km = []
            for item in km_ids:
                kid = str(item)
                if ids and kid not in ids:
                    raise ValueError("KM 不在候选：" + kid)
                if kid and kid not in clean_km:
                    clean_km.append(kid)
            clean_mat = []
            for item in material_ids:
                mid = str(item)
                if ids and mid not in ids:
                    raise ValueError("材料不在候选：" + mid)
                if mid and mid not in clean_mat:
                    clean_mat.append(mid)
            clean_pages = []
            for item in pages:
                if isinstance(item, dict):
                    clean_pages.append(
                        {
                            "km_id": str(item.get("km_id") or ""),
                            "material_name": str(item.get("material_name") or ""),
                            "page": str(item.get("page") or ""),
                            "page_title": str(item.get("page_title") or ""),
                            "order": str(item.get("order") or ""),
                            "approval_no": str(item.get("approval_no") or item.get("cn") or ""),
                            "source": str(item.get("source") or ""),
                        }
                    )
            mat_names = result.get("material_names") or []
            if not isinstance(mat_names, list):
                mat_names = []
            return {
                "status": status,
                "km_ids": clean_km,
                "selected_pages": clean_pages,
                "material_ids": clean_mat,
                "material_names": [str(x) for x in mat_names],
            }

        if step_name == "STRATEGY":
            code = str(result.get("strategy_code") or "")
            if code and ids and code not in ids:
                raise ValueError("策略编码不在候选：" + code)
            hit = self.lookup_strategy(code) if code else {}
            raw_name = str(
                result.get("strategy_name")
                or (hit.get("strategy_name") if isinstance(hit, dict) else "")
                or ""
            )
            return {
                "status": status,
                "strategy_code": code,
                "strategy_name": self.coach_strategy_name(code, raw_name),
                "strategy_desc": str(
                    result.get("strategy_desc")
                    or (hit.get("strategy_desc") if isinstance(hit, dict) else "")
                    or ""
                ),
                "custom_text": str(result.get("custom_text") or ""),
            }

        raise ValueError("未知 step：" + str(step_name))

    def one_click_draft_ready(self, card_state):
        steps = card_state.get("steps") or {}
        for key in ("opening", "explore", "barrier", "info_material", "strategy"):
            item = steps.get(key) or {}
            if not isinstance(item, dict):
                return False
            if key == "opening" and not (item.get("opening_id") or item.get("selected_id")):
                return False
            if key == "explore" and not (item.get("question_ids") or item.get("selected_ids")):
                return False
            if key == "km" and not item.get("km_ids"):
                return False
            if key == "info_material" and not item.get("km_ids"):
                return False
            if key == "strategy" and not item.get("strategy_code"):
                return False
        return True

