    def seed_pending_explore_if_empty(self, card_state):
        """逐步讲探寻时：无编号则塞默认题；有编号但题干空则补全文，便于 reply 复述。"""
        steps = card_state.get("steps") if isinstance(card_state.get("steps"), dict) else {}
        explore = dict(steps.get("explore") or {})
        qids = explore.get("question_ids") or explore.get("selected_ids") or []
        need_seed = False
        if not qids:
            qids = self.pick_default_explore_ids()
            need_seed = True
        has_text = False
        for q in explore.get("questions") or []:
            if isinstance(q, dict) and str(q.get("text") or "").strip():
                has_text = True
                break
        if need_seed or not has_text:
            explore["question_ids"] = list(qids)
            explore["questions"] = self.explore_questions_or_fallback(qids)
            if not explore.get("status"):
                explore["status"] = "PENDING"
            steps["explore"] = explore
            card_state["steps"] = steps
        return card_state

    def seed_pending_strategy_if_empty(self, card_state):
        """讲策略前：无编码则塞 CS 默认策略，避免 reply 只剩「推荐策略」。"""
        steps = card_state.get("steps") if isinstance(card_state.get("steps"), dict) else {}
        strategy = dict(steps.get("strategy") or {})
        if not str(strategy.get("strategy_code") or "").strip():
            stg = self.pick_default_strategy()
            strategy["strategy_code"] = str(stg.get("strategy_code") or stg.get("code") or "")
            strategy["strategy_name"] = str(stg.get("strategy_name") or "")
            if not strategy.get("status"):
                strategy["status"] = "PENDING"
            steps["strategy"] = strategy
            card_state["steps"] = steps
        return card_state

    def reply_has_label(self, reply, label):
        text = str(reply or "")
        lab = str(label or "").strip()
        if not lab or lab in ("推荐探寻题", "推荐策略", "推荐材料", "已选"):
            return False
        # 题干/策略名至少命中前 10 字，避免「换这道」空壳
        snip = lab[:10]
        return snip in text

    def build_edit_confirm_reply(self, card_state, edit_step):
        """换栏后必须复述具体内容，禁止只说「换这道/这条」。"""
        card_state = self.resolve_known_step_texts(card_state)
        steps = card_state.get("steps") or {}
        edit_step = str(edit_step or "").upper()
        if edit_step == "EXPLORE":
            card_state = self.seed_pending_explore_if_empty(card_state)
            card_state = self.resolve_known_step_texts(card_state)
            steps = card_state.get("steps") or {}
            label = self.step_label("explore", steps.get("explore") or {})
            return (
                "好，换一道探寻题。当前这道：\n「"
                + label
                + "」\n可以就回「可以」；还想再换直接说。"
            )
        if edit_step == "OPENING":
            opening = steps.get("opening") or {}
            direction = str(opening.get("direction_name") or "").strip() or "推荐方向"
            text = self.clean_opening_text(opening.get("text") or "")
            if not text:
                text = self.opening_full_label(opening)
            return (
                "好，换开场话术。当前方向「"
                + direction
                + "」：\n「"
                + text
                + "」\n可以就回「可以」；还想换方向（回顾上次拜访／客户近期动态／领域动态）或换一句，直接说。"
            )
        if edit_step == "STRATEGY":
            card_state = self.seed_pending_strategy_if_empty(card_state)
            card_state = self.resolve_known_step_texts(card_state)
            steps = card_state.get("steps") or {}
            label = self.step_label("strategy", steps.get("strategy") or {})
            return (
                "好，换沟通策略。当前这条：\n「"
                + label
                + "」\n（材料会随策略自动带）可以就回「可以」；还想再换直接说。"
            )
        return self.present_current_step_reply(card_state)

    def guide_back_hint(self, card_state):
        status = str(card_state.get("final_status") or "").upper()
        if status == "READY_TO_CONFIRM":
            return "手卡草案已经齐了，没问题就回我「确认生成」；想改哪一栏直接说。"
        if str(card_state.get("target_status") or "").upper() != "CONFIRMED":
            return "异议上游已经带好了，咱们先把本次要传的关键信息定下来：推荐还是那条 KM，您看定这条吗？"
        mode = str(card_state.get("mode") or "").upper()
        if mode not in ("STEPWISE", "ONE_CLICK"):
            return "目标定了，您看按步骤确认还是一键生成？"
        step = str(card_state.get("current_step") or "OPENING").upper()
        card_state = self.resolve_known_step_texts(card_state)
        steps = card_state.get("steps") or {}
        if step == "OPENING":
            opening = steps.get("opening") or {}
            direction = str(opening.get("direction_name") or "").strip() or "推荐方向"
            text = self.clean_opening_text(opening.get("text") or "")
            if not text:
                text = self.opening_full_label(opening)
            return (
                "咱们继续确认开场话术。当前方向「"
                + direction
                + "」：\n「"
                + text
                + "」\n可以就回「可以」；想换方向或换一句直接说。"
            )
        if step == "EXPLORE":
            card_state = self.seed_pending_explore_if_empty(card_state)
            card_state = self.resolve_known_step_texts(card_state)
            steps = card_state.get("steps") or {}
            label = self.step_label("explore", steps.get("explore") or {})
            return (
                "咱们继续确认探寻话术。当前这道：\n「"
                + label
                + "」\n可以就回「可以」；想换一道直接说。"
            )
        if step in ("BARRIER", "INFO_MATERIAL"):
            return "障碍/材料已按异议自动关联，接下来确认沟通策略就行。"
        if step == "STRATEGY":
            card_state = self.seed_pending_strategy_if_empty(card_state)
            card_state = self.resolve_known_step_texts(card_state)
            steps = card_state.get("steps") or {}
            label = self.step_label("strategy", steps.get("strategy") or {})
            return "咱们回到沟通策略这步。当前推荐：「" + label + "」。就用这条可以吗？"
        return "咱们还是把手卡这步定下来吧。"

    def keep_specialist_reply(self, reply):
        """专精 LLM（含闲聊）话术可保留：非空、非五栏甩盘、非误问目标。"""
        text = str(reply or "").strip()
        if not text:
            return False
        if self.reply_dumps_all_steps(text):
            return False
        if self.reply_asks_confirm_goal(text):
            return False
        return True

    def reply_asks_confirm_goal(self, reply):
        """模型误复读触发轮：在目标已确认后仍问定拜访目标。"""
        text = str(reply or "")
        keys = [
            "定拜访目标",
            "定本次拜访目标",
            "就用这条KM定",
            "就用这条 KM 定",
            "换候选里的另一条",
            "还是想换候选",
            "选定要传递的关键信息",
            "您看就用这条KM",
            "您看就用这条 KM",
        ]
        for key in keys:
            if key in text:
                return True
        return False

    def step_label(self, step_key, item):
        """给人看的短标签：只用名称/文案，禁止念内部编码。"""
        item = item if isinstance(item, dict) else {}
        if step_key == "opening":
            return str(
                item.get("direction_name")
                or item.get("text")
                or "推荐开场"
            )
        if step_key == "explore":
            texts = []
            for q in item.get("questions") or []:
                if isinstance(q, dict):
                    t = str(q.get("text") or "").strip()
                    if t:
                        texts.append(t)
            if not texts:
                # 从候选库按 id 补题干；查不到则走兜底文案
                qids = item.get("question_ids") or item.get("selected_ids") or []
                found = self.explore_questions_or_fallback(qids)
                for q in found:
                    t = str(q.get("text") or "").strip()
                    if t:
                        texts.append(t)
            if texts:
                # reply 里不宜太长：取首题，多题注明还有几道
                if len(texts) == 1:
                    return texts[0]
                return texts[0] + "（等" + str(len(texts)) + "题）"
            return "推荐探寻题"
        if step_key in ("km", "barrier"):
            # 主侧已确认异议：只展示、不让改。优先名称，其次主 agent 带来的正文。
            oname = str(item.get("objection_name") or item.get("barrier_name") or "").strip()
            if oname:
                return oname
            evidence = str(
                item.get("evidence")
                or item.get("objection_text")
                or item.get("barrier_evidence")
                or item.get("objection_evidence")
                or ""
            ).strip()
            if evidence:
                return evidence
            return "已确认异议"
        if step_key == "info_material":
            names = []
            for n in item.get("material_names") or []:
                t = str(n or "").strip()
                if t and t not in names:
                    names.append(t)
            if not names:
                for p in item.get("selected_pages") or []:
                    if not isinstance(p, dict):
                        continue
                    t = str(p.get("material_name") or "").strip()
                    if t and t not in names:
                        names.append(t)
            if names:
                if len(names) == 1:
                    return names[0]
                return names[0] + " 等" + str(len(names)) + "份材料"
            return "推荐材料"
        if step_key == "strategy":
            return str(item.get("strategy_name") or "推荐策略")
        return "已选"

    def km_display(self, card_state):
        """信息与材料栏：KM 文案（对人）。优先 candidates 库名，避免 scene 短名/异议串味。"""
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        kids = list(vg.get("km_ids") or [])
        texts = []
        looked = self.lookup_kms(kids) if kids else []
        for it in looked:
            s = str(it.get("km_name") or "").strip()
            if s and s not in texts:
                texts.append(s)
        if not texts:
            for t in vg.get("km_texts") or vg.get("km_names") or []:
                s = str(t or "").strip()
                if s and s not in texts:
                    texts.append(s)
        if not texts:
            items = vg.get("km_items") or []
            for it in items:
                if isinstance(it, dict):
                    s = str(it.get("km_name") or it.get("km_text") or "").strip()
                    if s and s not in texts:
                        texts.append(s)
        # 若唯一文案与异议名撞车，当作无效再空
        oname = str(vg.get("objection_name") or vg.get("barrier_name") or "").strip()
        if oname and texts and len(texts) == 1 and texts[0] == oname:
            texts = []
        if not texts:
            return ""
        if len(texts) == 1:
            return texts[0]
        return texts[0] + "（等" + str(len(texts)) + "条KM）"

    def clean_opening_text(self, text):
        """去掉库内弯引号叠套，避免 reply 出现「“...”」。"""
        t = str(text or "").strip()
        if len(t) >= 2 and t[0] in ("“", '"', "「") and t[-1] in ("”", '"', "」"):
            t = t[1:-1].strip()
        return t

    def opening_full_label(self, opening):
        opening = opening if isinstance(opening, dict) else {}
        direction = str(opening.get("direction_name") or "").strip()
        text = self.clean_opening_text(opening.get("text") or "")
        if not text and opening.get("opening_id"):
            hit = self.lookup_opening(opening.get("opening_id"))
            if isinstance(hit, dict):
                direction = direction or str(hit.get("direction_name") or "").strip()
                text = self.clean_opening_text(hit.get("text") or "")
        if direction and text:
            return direction + "：" + text
        if text:
            return text
        if direction:
            return "方向「" + direction + "」"
        return "推荐开场"

    def opening_priority_brief(self, sig):
        """三方向优先级说明：客户近期动态 > 回顾上次拜访 > 领域动态。"""
        sig = sig if isinstance(sig, dict) else {}
        recent = sig.get("recent_event") if isinstance(sig.get("recent_event"), dict) else {}
        has_recent = bool(
            sig.get("has_recent_event")
            or recent.get("event")
            or recent.get("theme")
            or recent.get("meeting")
        )
        has_last = bool(sig.get("has_last_visit"))
        prefer = str(sig.get("preferred_opening_direction") or "").strip() or "领域动态"
        lines = []
        if has_recent:
            ev = str(recent.get("event") or "近期活动")
            theme = str(recent.get("theme") or "")
            bit = "有「" + ev + "」"
            if theme:
                bit = bit + "／主题「" + theme + "」"
            lines.append("1）客户近期动态 — " + bit + "，本次优先")
        else:
            lines.append("1）客户近期动态 — 主侧暂无近期动态，本次不推")
        if has_last:
            lv = sig.get("last_visit") if isinstance(sig.get("last_visit"), dict) else {}
            note = str(lv.get("note") or "有上次拜访记录")
            lines.append("2）回顾上次拜访 — " + note + "，次优先")
        else:
            lines.append("2）回顾上次拜访 — 暂无上次拜访细节，先不推")
        if prefer == "领域动态":
            lines.append("3）领域动态 — 作本次推荐（有可用模板，避免空填会议/主题）")
        else:
            lines.append("3）领域动态 — 作兜底备选")
        return "开场常用三个方向，按主数据优先级：\n" + "\n".join(lines) + "\n因此推荐「" + prefer + "」。"

    def material_full_label(self, card_state, material):
        """信息与材料栏：KM + CN/材料名/页。"""
        parts = []
        km = self.km_display(card_state)
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        kids = list(vg.get("km_ids") or [])
        if km:
            if kids:
                parts.append("KM：" + str(kids[0]) + "｜" + km)
            else:
                parts.append("KM：" + km)
        material = material if isinstance(material, dict) else {}
        page_bits = []
        for p in material.get("selected_pages") or []:
            if not isinstance(p, dict):
                continue
            cn = str(p.get("approval_no") or p.get("cn") or "").strip()
            mn = str(p.get("material_name") or "").strip()
            page = str(p.get("page") or "").strip()
            title = str(p.get("page_title") or "").strip()
            chunk = ""
            if cn:
                chunk = cn
            if mn:
                chunk = (chunk + "｜" + mn) if chunk else mn
            if page:
                chunk = (chunk + " " + page) if chunk else page
            if title:
                chunk = (chunk + "「" + title + "」") if chunk else title
            if chunk:
                page_bits.append(chunk)
        if page_bits:
            parts.append("材料：" + page_bits[0] + ((" 等" + str(len(page_bits)) + "页") if len(page_bits) > 1 else ""))
        else:
            mat = self.step_label("info_material", material)
            if mat and mat != "推荐材料":
                parts.append("材料：" + mat)
            elif not parts:
                parts.append("推荐材料")
        return "；".join(parts)

    def opening_signals(self):
        g = self.loads(self.goal_context)
        if not isinstance(g, dict):
            g = {}
        sig = g.get("opening_signals")
        if isinstance(sig, dict):
            return sig
        block = (self.candidates_obj().get("step_candidates") or {}).get("OPENING") or {}
        if isinstance(block.get("signals"), dict):
            return block.get("signals")
        return {}

    def pick_default_opening(self):
        block = (self.candidates_obj().get("step_candidates") or {}).get("OPENING") or {}
        items = block.get("items") or []
        g = self.loads(self.goal_context)
        if not isinstance(g, dict):
            g = {}
        sig = self.opening_signals()
        recent = sig.get("recent_event") if isinstance(sig.get("recent_event"), dict) else {}
        has_real_recent = bool(
            recent.get("event") or recent.get("theme") or recent.get("meeting")
        )
        prefer = str(
            sig.get("preferred_opening_direction")
            or block.get("preferred_direction")
            or ""
        )
        hint = str(g.get("dynamic_hint") or sig.get("dynamic_hint") or "").upper()
        if has_real_recent:
            prefer = "客户近期动态"
        elif not prefer:
            prefer = "领域动态"
            if sig.get("has_last_visit") or "LAST" in hint or "回顾" in hint:
                prefer = "回顾上次拜访"
            elif "领域" in hint or hint == "DOMAIN":
                prefer = "领域动态"
        for item in items:
            if not isinstance(item, dict):
                continue
            if prefer and prefer in str(item.get("direction_name") or ""):
                row = dict(item)
                # 有近期动态时再填实一次占位
                if has_real_recent and prefer == "客户近期动态":
                    text = str(row.get("text") or "")
                    meeting = recent.get("event") or "近期学术活动"
                    theme = recent.get("theme") or "相关主题"
                    text = text.replace("【会议】", meeting).replace("【XX会议】", meeting)
                    text = text.replace("【主题】", theme).replace("【XXX话题】", theme)
                    row["text"] = text
                return row
        if items and isinstance(items[0], dict):
            return items[0]
        # 无数据兜底：领域动态，避免空填【会议】【主题】
        return {
            "id": "7",
            "opening_id": "7",
            "direction": "领域动态",
            "direction_name": "领域动态",
            "text": "近期指南/共识对相关评估点作了更新。我带来了对应资料，想请教您，这一变化在临床实践中有哪些值得讨论的地方？",
        }

    def pick_default_explore_ids(self):
        block = (self.candidates_obj().get("step_candidates") or {}).get("EXPLORE") or {}
        items = block.get("items") or []
        g = self.loads(self.goal_context)
        if not isinstance(g, dict):
            g = {}
        preferred = block.get("preferred_ids") or g.get("explore_preferred_ids") or []
        ids = []
        for item in items:
            if isinstance(item, dict) and item.get("id"):
                ids.append(str(item.get("id")))
        for qid in preferred:
            if str(qid) in ids:
                return [str(qid)]
        if ids:
            return [ids[0]]
        cs = str(g.get("cs_code") or "CS2").upper()
        fallback = {
            "CS1": "1.1",
            "CS2": "1.4",
            "CS3": "2.1",
            "CS4": "5",
        }
        return [fallback.get(cs, "1.4")]

    def pick_default_explore_fallback_questions(self, qids):
        # 必须与 01 LIBRARIES.explore_questions 题干一致，避免确认前后文案跳变
        catalog = {
            "1.1": "您在临床中遇到什么样的哮喘患者，会诊断为重度哮喘？",
            "1.4": "您认为患者血EOS超过多少值，属于嗜酸粒细胞性哮喘，并且会引起您的重视？",
            "2.1": "对于EOS升高的中/高剂量ICS/LABA未控制的患者，理想的治疗目标是什么？",
            "2.2": "对于EOS升高的中/高剂量ICS/LABA未控的哮喘患者，您会优先考虑哪种治疗方案？",
        }
        out = []
        for qid in qids or []:
            sid = str(qid)
            out.append({"id": sid, "text": catalog.get(sid, "推荐探寻题（" + sid + "）")})
        if not out:
            out = [{"id": "2.1", "text": catalog["2.1"]}]
        return out

    def explore_questions_or_fallback(self, qids):
        found = self.lookup_questions(qids)
        has_text = False
        for q in found:
            if str(q.get("text") or "").strip():
                has_text = True
                break
        if has_text:
            return found
        return self.pick_default_explore_fallback_questions(qids)

    def is_strategy_gap_name(self, name):
        """缺口标签形如「2 优先启用生物制剂，但不优先靶向EOS」，不宜对人展示。"""
        s = str(name or "").strip()
        if not s:
            return True
        if len(s) >= 2 and s[0].isdigit() and s[1] in (" ", ".", "、", "．"):
            return True
        if "但不优先" in s or "不关注" in s or "无法正常识别" in s:
            return True
        return False

    def coach_strategy_name(self, code, fallback=""):
        code = str(code or "").strip()
        name = STRATEGY_COACH_NAME.get(code) or ""
        if name:
            return name
        fb = str(fallback or "").strip()
        if fb and not self.is_strategy_gap_name(fb):
            return fb
        hit = self.lookup_strategy(code) if code else {}
        if isinstance(hit, dict):
            hit_name = str(hit.get("strategy_name") or "").strip()
            if hit_name and not self.is_strategy_gap_name(hit_name):
                return hit_name
        return fb or "优先靶向EOS，并结合患者负担与安全性做规范沟通"

    def pick_default_strategy(self):
        block = (self.candidates_obj().get("step_candidates") or {}).get("STRATEGY") or {}
        items = block.get("items") or []
        if items and isinstance(items[0], dict):
            row = dict(items[0])
            code = str(row.get("strategy_code") or row.get("code") or "")
            row["strategy_name"] = self.coach_strategy_name(code, row.get("strategy_name") or "")
            return row
        g = self.loads(self.goal_context)
        if not isinstance(g, dict):
            g = {}
        cs_code = str(g.get("cs_code") or g.get("csCode") or "CS3").upper()
        code = cs_code + "D01"
        return {
            "strategy_code": code,
            "strategy_name": self.coach_strategy_name(code),
            "strategy_desc": "",
        }

    def build_strategy_ready_reply(self, card_state):
        """策略确认后强制话术：复述已定策略名，引导确认生成。大模型傻话一律覆盖。"""
        card_state = self.resolve_known_step_texts(card_state)
        steps = card_state.get("steps") if isinstance(card_state.get("steps"), dict) else {}
        strategy = steps.get("strategy") if isinstance(steps.get("strategy"), dict) else {}
        code = str(strategy.get("strategy_code") or "").strip()
        name = self.coach_strategy_name(code, strategy.get("strategy_name") or "")
        return (
            "策略定了，这条「"
            + name
            + "」就用啦，材料页已自动关联。现在所有步骤都齐了，没问题就回我「确认生成」哦。"
        )

    def cn_of_material_name(self, material_name):
        name = str(material_name or "").strip()
        if not name:
            return ""
        info = (self.candidates_obj().get("step_candidates") or {}).get("INFO_MATERIAL") or {}
        for m in info.get("materials") or []:
            if not isinstance(m, dict):
                continue
            mn = str(m.get("name") or m.get("material_name") or "").strip()
            if mn == name:
                return str(m.get("approval_no") or m.get("cn") or "")
        return ""

    def normalize_material_page(self, pg, source=""):
        if not isinstance(pg, dict):
            return None
        mn = str(pg.get("material_name") or "").strip()
        return {
            "material_name": mn,
            "page": str(pg.get("page") or ""),
            "order": str(pg.get("order") or ""),
            "page_title": str(pg.get("page_title") or ""),
            "approval_no": str(
                pg.get("approval_no") or pg.get("cn") or self.cn_of_material_name(mn) or ""
            ),
            "source": str(pg.get("source") or source or "STRATEGY"),
        }

    def strategy_material_pages(self, card_state, strategy_code=None, limit=2):
        """沟通材料=策略子选项：取 candidates.STRATEGY[code].pages。"""
        steps = card_state.get("steps") if isinstance(card_state.get("steps"), dict) else {}
        st = steps.get("strategy") if isinstance(steps.get("strategy"), dict) else {}
        code = str(strategy_code or st.get("strategy_code") or "").strip()
        if not code:
            stg = self.pick_default_strategy()
            code = str(stg.get("strategy_code") or stg.get("code") or "")
        hit = self.lookup_strategy(code)
        if not hit:
            stg = self.pick_default_strategy()
            if str(stg.get("strategy_code") or stg.get("code") or "") == code or not hit:
                hit = stg if isinstance(stg, dict) else {}
        raw_pages = hit.get("pages") if isinstance(hit, dict) else None
        if not isinstance(raw_pages, list) or not raw_pages:
            return []
        out = []
        # 默认推首选 + 一条搭配（最多 limit）
        for pg in raw_pages:
            item = self.normalize_material_page(pg, source="STRATEGY:" + code)
            if item and item.get("material_name"):
                out.append(item)
            if limit and len(out) >= limit:
                break
        return out

    def sync_materials_from_strategy(self, card_state, force=False):
        """选定/更换策略后，把材料页同步成该策略的 pages 子选项。"""
        steps = card_state.get("steps") if isinstance(card_state.get("steps"), dict) else {}
        st = steps.get("strategy") if isinstance(steps.get("strategy"), dict) else {}
        code = str(st.get("strategy_code") or "").strip()
        if not code:
            return card_state
        material = dict(steps.get("info_material") or {})
        has_pages = bool(material.get("selected_pages") or material.get("material_names"))
        linked = str(material.get("linked_strategy_code") or "")
        if force or (not has_pages) or (linked and linked != code) or (not linked):
            pages = self.strategy_material_pages(card_state, strategy_code=code, limit=2)
            if pages:
                names = []
                for p in pages:
                    mn = str(p.get("material_name") or "").strip()
                    if mn and mn not in names:
                        names.append(mn)
                vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
                material["selected_pages"] = pages
                material["material_names"] = names
                material["linked_strategy_code"] = code
                material["km_ids"] = list(material.get("km_ids") or vg.get("km_ids") or [])
                if not material.get("status"):
                    material["status"] = "CONFIRMED"
                steps["info_material"] = material
                card_state["steps"] = steps
        return card_state

    def pick_default_material_pages(self, card_state):
        """默认材料页：优先策略 pages 子选项；否则回退异议/INFO_MATERIAL 页。"""
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        pages = self.strategy_material_pages(card_state, limit=2)
        if pages:
            return pages
        info = (self.candidates_obj().get("step_candidates") or {}).get("INFO_MATERIAL") or {}
        pages = []
        for pg in (info.get("pages") or [])[:1]:
            item = self.normalize_material_page(pg, source=vg.get("objection_source") or "")
            if item:
                pages.append(item)
        return pages

    def ensure_visit_goal_km_names(self, card_state):
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        kids = list(vg.get("km_ids") or [])
        if not kids:
            visit = (self.candidates_obj().get("step_candidates") or {}).get("VISIT_GOAL") or {}
            for it in visit.get("recommend_kms") or []:
                if isinstance(it, dict) and it.get("km_id"):
                    kids.append(str(it.get("km_id")))
                if len(kids) >= 2:
                    break
            vg["km_ids"] = kids
        names = list(vg.get("km_names") or [])
        texts = list(vg.get("km_texts") or [])
        if kids and (not names or not texts):
            looked = self.lookup_kms(kids)
            if not names:
                names = [str(x.get("km_name") or "") for x in looked if x.get("km_name")]
            if not texts:
                texts = list(names)
            vg["km_names"] = names
            vg["km_texts"] = texts
            if not vg.get("km_items"):
                vg["km_items"] = looked
        card_state["visit_goal"] = vg
        return card_state

    def default_one_click_step_result(self, card_state):
        """按 CS/异议/candidates 生成完整一键五步（有默认、无空壳）。"""
        card_state = self.ensure_visit_goal_km_names(card_state)
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        op = self.pick_default_opening()
        qids = self.pick_default_explore_ids()
        stg = self.pick_default_strategy()
        st_code = str(stg.get("strategy_code") or stg.get("code") or "")
        # 一键：材料直接取该策略 pages 子选项
        pages = self.strategy_material_pages(card_state, strategy_code=st_code, limit=2)
        if not pages:
            pages = self.pick_default_material_pages(card_state)
        names = []
        for p in pages:
            mn = str(p.get("material_name") or "").strip()
            if mn and mn not in names:
                names.append(mn)
        return {
            "opening": {
                "status": "PENDING",
                "opening_id": str(op.get("id") or op.get("opening_id") or "4"),
                "direction_code": str(op.get("direction") or op.get("direction_code") or ""),
                "direction_name": str(op.get("direction_name") or "客户近期动态"),
                "text": str(op.get("text") or ""),
            },
            "explore": {
                "status": "PENDING",
                "question_ids": qids,
                "questions": self.explore_questions_or_fallback(qids),
                "note": "",
            },
            "barrier": {
                "status": "PENDING",
                "objection_source": vg.get("objection_source") or "",
                "objection_id": vg.get("objection_id") or vg.get("barrier_id") or "",
                "objection_name": vg.get("objection_name") or vg.get("barrier_name") or "",
                "evidence": vg.get("objection_text") or "",
            },
            "info_material": {
                "status": "PENDING",
                "material_names": names,
                "selected_pages": pages,
                "material_ids": [],
                "km_ids": list(vg.get("km_ids") or []),
                "linked_strategy_code": st_code,
            },
            "strategy": {
                "status": "PENDING",
                "strategy_code": str(stg.get("strategy_code") or "CS1D01"),
                "strategy_name": str(stg.get("strategy_name") or ""),
                "custom_text": "",
            },
        }

    def resolve_known_step_texts(self, card_state):
        """只给「已有编号」补全文，写入 steps；不凭空塞未开始的步。

        下一轮 LLM/主侧读 card_state 时：既有 opening_id 也有 text；
        用户看到的 history 是 reply 话术，不是编号。
        """
        card_state = self.ensure_visit_goal_km_names(card_state)
        steps = card_state.get("steps")
        if not isinstance(steps, dict):
            steps = {}

        opening = dict(steps.get("opening") or {})
        if opening.get("opening_id"):
            hit = self.lookup_opening(opening.get("opening_id"))
            if isinstance(hit, dict) and hit:
                opening["direction_name"] = opening.get("direction_name") or hit.get("direction_name") or ""
                opening["text"] = opening.get("text") or hit.get("text") or ""
                if not opening.get("direction_code"):
                    opening["direction_code"] = str(hit.get("direction") or hit.get("direction_code") or "")
        steps["opening"] = opening

        explore = dict(steps.get("explore") or {})
        qids = explore.get("question_ids") or explore.get("selected_ids") or []
        if qids:
            explore["question_ids"] = list(qids)
            # 候选若未带 EXPLORE（旧收窄）也要用兜底题干，避免空 text
            explore["questions"] = self.explore_questions_or_fallback(qids)
        steps["explore"] = explore

        barrier = dict(steps.get("barrier") or {})
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        if barrier.get("objection_id") or vg.get("objection_id") or vg.get("objection_text"):
            barrier["objection_id"] = barrier.get("objection_id") or vg.get("objection_id") or vg.get("barrier_id") or ""
            barrier["objection_source"] = (
                barrier.get("objection_source") or vg.get("objection_source") or ""
            )
            barrier["objection_name"] = (
                barrier.get("objection_name")
                or vg.get("objection_name")
                or vg.get("barrier_name")
                or ""
            )
            # 主 agent 带来的异议正文优先（短 evidence 如「安全性」不盖掉 objection_text）
            vg_text = str(vg.get("objection_text") or "").strip()
            cur_ev = str(barrier.get("evidence") or "").strip()
            if vg_text and (not cur_ev or len(vg_text) > len(cur_ev)):
                barrier["evidence"] = vg_text
            elif not cur_ev:
                barrier["evidence"] = vg_text
            if not barrier.get("objection_name") and barrier.get("evidence"):
                barrier["objection_name"] = str(barrier.get("evidence") or "")
        steps["barrier"] = barrier

        material = dict(steps.get("info_material") or {})
        pages = material.get("selected_pages") or []
        names = list(material.get("material_names") or [])
        if pages and not names:
            for p in pages:
                if isinstance(p, dict):
                    mn = str(p.get("material_name") or "").strip()
                    if mn and mn not in names:
                        names.append(mn)
            material["material_names"] = names
        if not material.get("km_ids"):
            material["km_ids"] = list(vg.get("km_ids") or [])
        steps["info_material"] = material

        strategy = dict(steps.get("strategy") or {})
        code = strategy.get("strategy_code")
        if code:
            hit = self.lookup_strategy(code)
            hit_name = ""
            if isinstance(hit, dict) and hit:
                hit_name = str(hit.get("strategy_name") or "")
                strategy["strategy_desc"] = strategy.get("strategy_desc") or hit.get("strategy_desc") or ""
            cur_name = str(strategy.get("strategy_name") or "")
            # 缺口标签 / 空名 → 一律换成沟通策略话术
            if (not cur_name) or self.is_strategy_gap_name(cur_name):
                strategy["strategy_name"] = self.coach_strategy_name(code, hit_name or cur_name)
            else:
                strategy["strategy_name"] = cur_name
        steps["strategy"] = strategy

        card_state["steps"] = steps
        return card_state

    def enrich_steps_for_display(self, card_state):
        """一键/整卡草案：缺步用 CS·异议·candidates 默认补齐；再 resolve 全文。"""
        mode = str(card_state.get("mode") or "").upper()
        status = str(card_state.get("final_status") or "").upper()
        need_defaults = mode == "ONE_CLICK" or status == "READY_TO_CONFIRM"
        if need_defaults:
            card_state = self.ensure_visit_goal_km_names(card_state)
            steps = card_state.get("steps")
            if not isinstance(steps, dict):
                steps = {}
            defaults = self.default_one_click_step_result(card_state)

            def keep_confirmed(prev, filled):
                """补默认文案时不得把已 CONFIRMED 打回 PENDING。"""
                out = dict(filled or {})
                if str((prev or {}).get("status") or "").upper() == "CONFIRMED":
                    out["status"] = "CONFIRMED"
                return out

            opening = dict(steps.get("opening") or {})
            if not opening.get("opening_id") and not opening.get("text"):
                opening = keep_confirmed(opening, defaults["opening"])
            elif opening.get("opening_id") and not (
                str(opening.get("text") or "").strip()
                or str(opening.get("direction_name") or "").strip()
            ):
                # 有编号无文案：用默认补全文，保留原 id
                filled = dict(defaults["opening"])
                filled["opening_id"] = opening.get("opening_id")
                if str(opening.get("status") or "").upper() == "CONFIRMED":
                    filled["status"] = "CONFIRMED"
                opening = filled
            steps["opening"] = opening

            explore = dict(steps.get("explore") or {})
            qids = explore.get("question_ids") or []
            if not qids:
                explore = keep_confirmed(explore, defaults["explore"])
            else:
                qs = self.lookup_questions(qids)
                has_text = False
                for q in qs:
                    if str(q.get("text") or "").strip():
                        has_text = True
                        break
                if not has_text:
                    # id 查不到文案：整步回退到默认推荐（避免「推荐探寻题」空壳）
                    explore = keep_confirmed(explore, defaults["explore"])
            steps["explore"] = explore

            barrier = dict(steps.get("barrier") or {})
            if not barrier.get("objection_id"):
                barrier = keep_confirmed(barrier, defaults["barrier"])
            steps["barrier"] = barrier

            material = dict(steps.get("info_material") or {})
            if not (material.get("material_names") or material.get("selected_pages")):
                material = keep_confirmed(material, defaults["info_material"])
            steps["info_material"] = material

            strategy = dict(steps.get("strategy") or {})
            prev_strategy = dict(strategy)
            if not strategy.get("strategy_code"):
                strategy = keep_confirmed(prev_strategy, defaults["strategy"])
            else:
                hit = self.lookup_strategy(strategy.get("strategy_code"))
                if isinstance(hit, dict) and hit:
                    strategy["strategy_name"] = (
                        strategy.get("strategy_name") or hit.get("strategy_name") or ""
                    )
                    strategy["strategy_desc"] = (
                        strategy.get("strategy_desc") or hit.get("strategy_desc") or ""
                    )
                if not str(strategy.get("strategy_name") or "").strip():
                    filled = dict(defaults["strategy"])
                    if prev_strategy.get("strategy_code"):
                        filled["strategy_code"] = prev_strategy.get("strategy_code")
                    strategy = keep_confirmed(prev_strategy, filled)
            steps["strategy"] = strategy
            card_state["steps"] = steps

        return self.resolve_known_step_texts(card_state)

    def render_five_card_blocks(self, card_state):
        """按业务五栏渲染给人看的正文（编号→全文；一键缺省从 candidates 补齐）。"""
        card_state = self.enrich_steps_for_display(card_state)
        steps = card_state.get("steps") or {}
        opening = steps.get("opening") or {}
        explore = steps.get("explore") or {}
        barrier = steps.get("barrier") or {}
        material = steps.get("info_material") or {}
        strategy = steps.get("strategy") or {}
        lines = [
            "①开场话术：" + self.opening_full_label(opening),
            "②探寻与回答：" + self.step_label("explore", explore),
            "③障碍移除：" + self.step_label("barrier", barrier),
            "④信息与材料：" + self.material_full_label(card_state, material),
            "⑤沟通策略：" + self.step_label("strategy", strategy),
        ]
        return "\n".join(lines)

    def build_one_click_draft_reply(self, card_state):
        body = self.render_five_card_blocks(card_state)
        return (
            "行，我按推荐一键出了整张草案，您过一眼：\n"
            + body
            + "\n没问题就回我「确认生成」；想改哪一步直接说。"
        )

    def build_mode_choice_summary(self, card_state):
        """目标确认后：只问逐步还是一键（不甩五栏全文；逐步时每轮只出一步）。"""
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        goal = str(vg.get("text") or "").strip() or "已确认的拜访目标"
        return (
            "拜访目标已定：「"
            + goal
            + "」\n接下来您想「按步骤确认」（每次只定一栏），还是「一键生成」整张草案？"
        )

    def present_current_step_reply(self, card_state):
        """逐步模式：沟通引导式话术；必须复述正文；有 sense 不做成题感。"""
        card_state = self.resolve_known_step_texts(card_state)
        step = str(card_state.get("current_step") or "OPENING").upper()
        steps = card_state.get("steps") or {}
        done = self.count_confirmed(card_state)
        g = self.loads(self.goal_context)
        if not isinstance(g, dict):
            g = {}
        cs = str(g.get("cs_code") or "").upper() or "当前CS"
        sig = self.opening_signals()
        if step == "OPENING":
            opening = steps.get("opening") or {}
            prefer = str(sig.get("preferred_opening_direction") or "")
            cur_dir = str(opening.get("direction_name") or "")
            need_reseed = (not opening.get("opening_id")) or (
                prefer
                and prefer not in cur_dir
                and str(opening.get("status") or "").upper() != "CONFIRMED"
            )
            if need_reseed:
                op = self.pick_default_opening()
                opening = {
                    "status": "PENDING",
                    "opening_id": str(op.get("id") or op.get("opening_id") or ""),
                    "direction_name": str(op.get("direction_name") or ""),
                    "text": str(op.get("text") or ""),
                }
                steps["opening"] = opening
                card_state["steps"] = steps
                card_state = self.resolve_known_step_texts(card_state)
                steps = card_state.get("steps") or {}
                opening = steps.get("opening") or {}
            label = self.opening_full_label(opening)
            direction = str(opening.get("direction_name") or sig.get("preferred_opening_direction") or "推荐方向")
            text = self.clean_opening_text(opening.get("text") or "")
            if not text:
                text = label
            priority = self.opening_priority_brief(sig)
            return (
                "拜访目标定了，咱们一项项对齐手卡（"
                + str(done)
                + "/5）。\n"
                "那么接下来我们确认本次拜访的开场话术。\n"
                + priority
                + "\n推荐开场（"
                + direction
                + "）：\n「"
                + text
                + "」\n"
                "可以就回我「可以」；想换方向（回顾上次拜访／客户近期动态／领域动态）或换一句，直接说。"
            )
        if step == "EXPLORE":
            card_state = self.seed_pending_explore_if_empty(card_state)
            card_state = self.resolve_known_step_texts(card_state)
            steps = card_state.get("steps") or {}
            explore = steps.get("explore") or {}
            q = self.step_label("explore", explore)
            return (
                "开场先这样。那么接下来我们确认本次拜访的探寻话术（"
                + str(done)
                + "/5）。\n"
                "按 "
                + cs
                + " 等级从话术库挑了一道，用来摸清医生对血 EOS 的思路：\n「"
                + q
                + "」\n"
                "可以就回我「可以」；想换一道更贴他关注点的题，直接说。"
            )
        if step in ("BARRIER", "INFO_MATERIAL"):
            # 障碍/材料不需用户确认：改讲策略
            card_state = self.auto_confirm_linked_steps(card_state)
            card_state["current_step"] = "STRATEGY"
            return self.present_current_step_reply(card_state)
        if step == "STRATEGY":
            card_state = self.seed_pending_strategy_if_empty(card_state)
            card_state = self.resolve_known_step_texts(card_state)
            steps = card_state.get("steps") or {}
            explore = steps.get("explore") or {}
            strategy = steps.get("strategy") or {}
            material = steps.get("info_material") or {}
            barrier = steps.get("barrier") or {}
            q = self.step_label("explore", explore)
            s = self.step_label("strategy", strategy)
            bname = self.step_label("barrier", barrier)
            mat = self.material_full_label(card_state, material)
            return (
                "探寻先落定：「"
                + q
                + "」。\n"
                "障碍移除这边主侧已经确认过了（"
                + bname
                + "），材料也按拜访目标/KM 自动挂上了："
                + mat
                + "。\n"
                "那么接下来我们确认本次拜访的沟通策略（"
                + str(self.count_confirmed(card_state))
                + "/5）：\n「"
                + s
                + "」\n"
                "这条策略会带着材料页一起走。可以就回我「可以」／「就用这条」；想换策略直接说。"
            )
        return self.build_progress_reply(card_state)

    def reply_dumps_all_steps(self, text):
        """检测 reply 是否一次甩出多栏（逐步模式应禁止）。"""
        raw = str(text or "")
        hits = 0
        for key in ("①", "②", "③", "④", "⑤", "开场话术", "探寻与回答", "障碍移除", "信息与材料", "沟通策略"):
            if key in raw:
                hits += 1
        if "①" in raw and "⑤" in raw:
            return True
        if hits >= 3:
            return True
        return False

    def awaiting_mode_choice(self, card_state):
        """目标已确认、尚未选定 STEPWISE/ONE_CLICK。"""
        if str(card_state.get("target_status") or "").upper() != "CONFIRMED":
            return False
        mode = str(card_state.get("mode") or "").upper()
        if mode in ("STEPWISE", "ONE_CLICK"):
            return False
        if str(card_state.get("final_status") or "").upper() == "CONFIRMED":
            return False
        return True

    def seed_recommended_draft(self, card_state):
        """写入推荐五步（PENDING），供 Summary / 一键共用。"""
        defaults = self.default_one_click_step_result(card_state)
        steps = card_state.get("steps")
        if not isinstance(steps, dict):
            steps = {}
        for key in ("opening", "explore", "barrier", "info_material", "strategy"):
            item = dict(defaults.get(key) or {})
            item["status"] = "PENDING"
            steps[key] = item
        card_state["steps"] = steps
        return self.resolve_known_step_texts(card_state)

