    def pick_alternate_step_result(self, card_state, step_name, text):
        """用户说换但模型没给新编号时：从本轮 candidates / 本地库轮换下一项。"""
        step_name = str(step_name or "").upper()
        steps = card_state.get("steps") if isinstance(card_state.get("steps"), dict) else {}
        cands = (self.candidates_obj().get("step_candidates") or {})
        text = str(text or "")

        if step_name == "OPENING":
            items = (cands.get("OPENING") or {}).get("items") or []
            ids = []
            for item in items:
                if isinstance(item, dict) and item.get("id"):
                    ids.append(str(item.get("id")))
            cur = str(((steps.get("opening") or {}).get("opening_id") or ""))
            # 话术点名方向
            prefer = ""
            if "领域" in text:
                prefer = "领域动态"
            elif "回顾" in text or "上次" in text:
                prefer = "回顾上次拜访"
            elif "近期" in text or "会议" in text:
                prefer = "客户近期动态"
            chosen = ""
            if prefer:
                for item in items:
                    if not isinstance(item, dict):
                        continue
                    if prefer in str(item.get("direction_name") or "") and str(item.get("id")) != cur:
                        chosen = str(item.get("id"))
                        break
            if not chosen and ids:
                if cur in ids:
                    chosen = ids[(ids.index(cur) + 1) % len(ids)]
                else:
                    chosen = ids[0]
            if not chosen:
                return self.recommended_opening_confirm(card_state)
            hit = {}
            for item in items:
                if isinstance(item, dict) and str(item.get("id")) == chosen:
                    hit = item
                    break
            return {
                "status": "CONFIRMED",
                "opening_id": chosen,
                "direction_code": str(hit.get("direction") or hit.get("direction_code") or ""),
                "direction_name": str(hit.get("direction_name") or ""),
                "text": str(hit.get("text") or ""),
            }

        if step_name == "EXPLORE":
            items = (cands.get("EXPLORE") or {}).get("items") or []
            ids = []
            for item in items:
                if isinstance(item, dict) and item.get("id"):
                    ids.append(str(item.get("id")))
            cur_list = (steps.get("explore") or {}).get("question_ids") or []
            cur = str(cur_list[0]) if cur_list else ""
            chosen = ""
            # 话术里带题号
            for qid in ids:
                if qid in text and qid != cur:
                    chosen = qid
                    break
            if not chosen and ids:
                if cur in ids:
                    chosen = ids[(ids.index(cur) + 1) % len(ids)]
                else:
                    chosen = ids[0]
            if not chosen:
                return self.recommended_explore_confirm(card_state)
            return {"status": "CONFIRMED", "question_ids": [chosen], "note": ""}

        if step_name == "STRATEGY":
            items = (cands.get("STRATEGY") or {}).get("items") or []
            codes = []
            for item in items:
                if not isinstance(item, dict):
                    continue
                code = str(item.get("strategy_code") or item.get("code") or item.get("id") or "")
                if code:
                    codes.append(code)
            cur = str(((steps.get("strategy") or {}).get("strategy_code") or ""))
            chosen = ""
            for code in codes:
                if code in text and code != cur:
                    chosen = code
                    break
            if not chosen and codes:
                if cur in codes:
                    chosen = codes[(codes.index(cur) + 1) % len(codes)]
                else:
                    chosen = codes[0]
            if not chosen:
                return self.recommended_strategy_confirm(card_state)
            return {"status": "CONFIRMED", "strategy_code": chosen, "custom_text": ""}

        return {}

    def build_progress_reply(self, card_state):
        """逐步推进后的人性化承接话术（防串回定目标）。"""
        done = self.count_confirmed(card_state)
        step = str(card_state.get("current_step") or "").upper()
        steps = card_state.get("steps") or {}
        opening = steps.get("opening") or {}
        if step == "EXPLORE" or (
            str(opening.get("status") or "").upper() == "CONFIRMED" and step in ("", "NONE")
        ):
            return (
                "开场这句就这么定了，进度 "
                + str(done)
                + "/5。探寻我推荐先用那道阈值相关题，摸清他对血 EOS 的看法。就用这题可以吗？"
            )
        if step == "BARRIER":
            return (
                "探寻定了，进度 "
                + str(done)
                + "/5。障碍移除只展示上游已确认异议，您看直接确认落库？"
            )
        if step == "INFO_MATERIAL":
            return (
                "异议已落库，进度 "
                + str(done)
                + "/5。材料我按该异议来源页推一版，您看行不行？"
            )
        if step == "STRATEGY":
            return (
                "材料定了，进度 "
                + str(done)
                + "/5。策略按 CS 推荐走可以吗？"
            )
        if step == "OPENING":
            return "拜访目标已经定好了。开场我建议用「客户近期动态」那句，您看就用这句吗？"
        return "好，这步记下了。咱们继续把手卡下一格定下来吧。"

    def humanize_reply(self, card_state, reply, reply_type):
        """状态对了但模型话术串台时，用更口语的承接覆盖。

        注意：代表主动改拜访目标时，允许 reply 谈「换 KM / 新目标」，不要误杀。
        """
        status = str(card_state.get("final_status") or "").upper()
        target = str(card_state.get("target_status") or "").upper()
        mode = str(card_state.get("mode") or "").upper()
        rt = str(reply_type or "").upper()
        text = str(reply or "").strip()
        # 主动改目标：保留模型话术（脚本已改 visit_goal），不要误盖成「定探寻」
        if self.user_wants_revise_goal():
            return text

        # 闲聊专精：先答再拉回；拉回必须复述当前步具体内容（避免 LLM+脚本各说一遍）
        if rt == "CHITCHAT":
            hint = self.guide_back_hint(card_state)
            if self.keep_specialist_reply(text):
                steps = card_state.get("steps") or {}
                step = str(card_state.get("current_step") or "").upper()
                label = ""
                if step == "EXPLORE":
                    label = self.step_label("explore", steps.get("explore") or {})
                elif step == "OPENING":
                    label = self.opening_full_label(steps.get("opening") or {})
                elif step == "STRATEGY":
                    label = self.step_label("strategy", steps.get("strategy") or {})
                # LLM 已写出题干/策略名 → 原样保留，不再追加脚本拉回
                if label and self.reply_has_label(text, label):
                    return text
                if hint in text:
                    return text
                first = text
                for sep in ("。", "！", "？", "～", "~", "\n"):
                    if sep in text:
                        first = text.split(sep, 1)[0] + sep
                        break
                first = first.strip() or text.strip()
                return (first + " " + hint).strip()
            return "这个我只能简单接一下～ " + hint

        if status == "CONFIRMED":
            return self.build_final_reply(card_state)

        # 整卡待确认时用户要改某一栏：不要盖成五步汇总；但空壳「换这道」要补正文
        if self.user_wants_edit() and status in ("READY_TO_CONFIRM", "GENERATING"):
            steps = card_state.get("steps") or {}
            if "探寻" in str(self.user_input or "") or "问题" in str(self.user_input or ""):
                label = self.step_label("explore", steps.get("explore") or {})
                if not self.reply_has_label(text, label):
                    return self.build_edit_confirm_reply(card_state, "EXPLORE")
            if "开场" in str(self.user_input or ""):
                label = self.opening_full_label(steps.get("opening") or {})
                if not self.reply_has_label(text, label):
                    return self.build_edit_confirm_reply(card_state, "OPENING")
            if "策略" in str(self.user_input or "") or "材料" in str(self.user_input or ""):
                label = self.step_label("strategy", steps.get("strategy") or {})
                if not self.reply_has_label(text, label):
                    return self.build_edit_confirm_reply(card_state, "STRATEGY")
            return text

        # 逐步五步齐 → READY：策略确认话术由脚本钉死（防大模型改成缺口标签 / 再问「就用吗」）
        if status == "READY_TO_CONFIRM" and mode == "STEPWISE":
            strategy = ((card_state.get("steps") or {}).get("strategy")) or {}
            if str(strategy.get("status") or "").upper() == "CONFIRMED":
                ready = self.build_strategy_ready_reply(card_state)
                sname = self.coach_strategy_name(
                    strategy.get("strategy_code") or "", strategy.get("strategy_name") or ""
                )
                # 仅当模型已写出正确策略名 + 确认生成，才保留；否则一律脚本
                if (
                    sname
                    and sname in text
                    and "确认生成" in text
                    and "但不优先" not in text
                    and "可以吗" not in text
                ):
                    return text
                return ready

        # 专精 LLM 已给出单步话术（如改探寻 STAY）：有正文才保留
        if status == "READY_TO_CONFIRM" and rt == "STEP" and self.keep_specialist_reply(text):
            explore = ((card_state.get("steps") or {}).get("explore")) or {}
            label = self.step_label("explore", explore)
            if "探寻" in text and label and not self.reply_has_label(text, label):
                return self.build_edit_confirm_reply(card_state, "EXPLORE")
            return text

        if status == "READY_TO_CONFIRM" or (mode == "ONE_CLICK" and rt == "FINAL_CONFIRM"):
            if mode == "STEPWISE":
                strategy = ((card_state.get("steps") or {}).get("strategy")) or {}
                if str(strategy.get("status") or "").upper() == "CONFIRMED":
                    return self.build_strategy_ready_reply(card_state)
                body = self.render_five_card_blocks(card_state)
                return (
                    "五步都定了，汇总如下：\n"
                    + body
                    + "\n没问题就回我「确认生成」。"
                )
            if self.reply_asks_confirm_goal(text) or "确认生成" not in text:
                return self.build_one_click_draft_reply(card_state)
            return text

        # 目标已定、待选逐步/一键：只短问模式（不甩五栏）
        if self.awaiting_mode_choice(card_state):
            return self.build_mode_choice_summary(card_state)

        # 逐步：强制每轮只讲当前一步
        if mode == "STEPWISE" and status not in ("READY_TO_CONFIRM", "CONFIRMED"):
            weak = (
                not text
                or text in ("好，按您刚才说的继续。", "好的", "好")
                or text.startswith("好，按您刚才说的")
            )
            if (
                weak
                or self.reply_dumps_all_steps(text)
                or self.reply_asks_confirm_goal(text)
                or ("按步骤确认" in text and "一键生成" in text)
            ):
                return self.present_current_step_reply(card_state)
            return text

        if target == "CONFIRMED" and self.reply_asks_confirm_goal(text):
            return self.build_progress_reply(card_state)

        return text

    def user_wants_one_click(self):
        """识别「直接出整张」意图。与目标同轮说「直接生成手卡」也应命中。"""
        text = str(self.user_input or "")
        keys = [
            "一键",
            "整张",
            "整卡",
            "直接出",
            "直接生成",
            "生成手卡",
            "生成整张",
            "生成草案",
            "一次生成",
            "一次出",
            "出草案",
            "出整张",
            "你看着办",
            "别一步步",
            "别逐步",
            "不要逐步",
            "不用逐步",
            "不用一步步",
        ]
        for key in keys:
            if key in text:
                return True
        return False

    def user_wants_stepwise(self):
        text = str(self.user_input or "")
        # 测例/快捷语常用「一项项来」；须与「按步骤」同等进入 STEPWISE
        keys = [
            "按步骤",
            "逐步",
            "一步步",
            "分步",
            "一步一",
            "按步",
            "一项项",
            "一项一项",
            "一步一项",
        ]
        for key in keys:
            if key in text:
                return True
        return False

    def user_marks_confirm(self):
        text = str(self.user_input or "")
        # 用户正在「换/改」时不算确认（避免「领域动态」里的「定」误触发）
        if self.user_wants_edit():
            return False
        keys = ["定了", "确认", "就这样", "没问题", "可以", "就用", "好的", "行"]
        for key in keys:
            if key in text:
                return True
        # 单独「定」易误伤（动态/固定…），仅整句短确认时用
        t = text.strip()
        if t in ("定", "ok", "OK", "好", "嗯"):
            return True
        return False

    def coerce_raw_from_user(self, card_state, raw):
        """口语短句确认时，模型常漏 step_result；按当前步 + 明确 id 兜底。"""
        if not isinstance(raw, dict):
            raw = {}
        if self.looks_like_offtopic():
            return raw
        text = str(self.user_input or "")
        step = str(card_state.get("current_step") or "").upper()
        status = str(card_state.get("final_status") or "").upper()

        # 已就绪时用户确认 → 交给 finish 逻辑（强制覆盖模型误写成「确认拜访目标」的话术）
        if status == "READY_TO_CONFIRM" and self.user_confirms_final():
            raw["reply_type"] = "DONE"
            raw["action"] = "FINISH"
            raw["card_status"] = "CONFIRMED"
            raw["step_result"] = {}
            raw["reply"] = self.build_final_reply(card_state)
            raw["reason"] = "整卡确认生成 → final_card"
            return raw

        # 五步已齐但还停在 GENERATING：抬到 READY，或直接收口
        if self.count_confirmed(card_state) == 5 and self.user_confirms_final():
            raw["reply_type"] = "DONE"
            raw["action"] = "FINISH"
            raw["card_status"] = "CONFIRMED"
            raw["step_result"] = {}
            raw["reply"] = self.build_final_reply(card_state)
            raw["reason"] = "五步已齐+确认生成 → final_card"
            return raw

        # 一键意图但目标未确认：先问定目标（本轮不落 confirm_target，避免 apply 同轮直接一键）
        if (
            self.user_wants_one_click()
            and str(card_state.get("target_status") or "").upper() != "CONFIRMED"
            and status != "CONFIRMED"
        ):
            raw["reply_type"] = "STEP"
            raw["action"] = "STAY"
            raw["step"] = None
            raw["confirm_target"] = False
            raw["card_status"] = "GENERATING"
            raw["mode"] = None
            raw["step_result"] = {}
            draft = dict(card_state)
            draft = self.ensure_visit_goal_km_names(draft)
            vg = draft.get("visit_goal") if isinstance(draft.get("visit_goal"), dict) else {}
            km_label = ""
            kids = vg.get("km_ids") or []
            names = vg.get("km_names") or vg.get("km_texts") or []
            if kids and names:
                km_label = str(kids[0]) + "｜" + str(names[0])
            elif kids:
                km_label = str(kids[0])
            else:
                km_label = "推荐 KM"
            raw["reply"] = (
                "一键生成前先把拜访目标定下来。推荐传递「"
                + km_label
                + "」，您看就定这条吗？"
            )
            raw["reason"] = "one_click_blocked_need_visit_goal"
            return raw

        # 目标已定、待选模式：逐步 or 一键
        if self.awaiting_mode_choice(card_state):
            if self.user_wants_one_click():
                raw["reply_type"] = "FINAL_CONFIRM"
                raw["action"] = "STAY"
                raw["mode"] = "ONE_CLICK"
                raw["card_status"] = "READY_TO_CONFIRM"
                raw["step"] = None
                raw["step_result"] = self.default_one_click_step_result(card_state)
                raw["reply"] = self.build_one_click_draft_reply(card_state)
                raw["reason"] = "mode_choice→ONE_CLICK"
                return raw
            # 明确逐步，或用户已在谈开场/就用推荐（默认进逐步，不卡在选模式）
            # 专精 LLM 已给出 mode=STEPWISE + OPENING 时也采信（避免「一项项来」漏词挡门）
            llm_stepwise = (
                str(raw.get("mode") or "").upper() == "STEPWISE"
                and str(raw.get("step") or "").upper() == "OPENING"
            )
            enter_stepwise = (
                self.user_wants_stepwise()
                or llm_stepwise
                or (
                    self.user_marks_confirm()
                    and (
                        "开场" in text
                        or "就用" in text
                        or "推荐" in text
                        or "第一步" in text
                    )
                )
            )
            if enter_stepwise:
                draft = dict(card_state)
                draft["mode"] = "STEPWISE"
                draft["current_step"] = "OPENING"
                if not ((draft.get("steps") or {}).get("opening") or {}).get("opening_id"):
                    draft = self.seed_recommended_draft(draft)
                # 「按步骤」→ 只出开场问句；「就用推荐/确认开场」→ 同轮落开场并只讲探寻
                advance_opening = (
                    self.user_marks_confirm()
                    and ("开场" in text or "就用" in text or "推荐" in text)
                    and not self.user_wants_stepwise()
                )
                if advance_opening:
                    raw["reply_type"] = "STEP"
                    raw["action"] = "ADVANCE"
                    raw["mode"] = "STEPWISE"
                    raw["card_status"] = "GENERATING"
                    raw["step"] = "OPENING"
                    raw["step_result"] = self.recommended_opening_confirm(draft)
                    raw["reply"] = "开场先按推荐定。"  # ADVANCE 后 result 会改成只讲下一步
                    raw["reason"] = "mode_choice→STEPWISE+确认开场"
                    return raw
                raw["reply_type"] = "STEP"
                raw["action"] = "STAY"
                raw["mode"] = "STEPWISE"
                raw["card_status"] = "GENERATING"
                raw["step"] = "OPENING"
                raw["step_result"] = {}
                raw["reply"] = self.present_current_step_reply(draft)
                raw["reason"] = "mode_choice→STEPWISE（只出开场）"
                return raw
            # 仍未选：短问模式
            raw["reply_type"] = "SUMMARY"
            raw["action"] = "PRESENT_SUMMARY"
            raw["mode"] = None
            raw["card_status"] = "GENERATING"
            raw["step"] = None
            raw["step_result"] = {}
            raw["reply"] = self.build_mode_choice_summary(card_state)
            raw["reason"] = "awaiting_mode_choice"
            return raw

        # 一键意图：合成五步草案（模型常漏 step_result）
        if (
            str(card_state.get("target_status") or "").upper() == "CONFIRMED"
            and self.user_wants_one_click()
            and status != "CONFIRMED"
        ):
            sr0 = raw.get("step_result")
            has_full = isinstance(sr0, dict) and (
                "opening" in sr0 and "explore" in sr0 and ("barrier" in sr0 or "km" in sr0)
            )
            if not has_full:
                # 兼容模型仍写 km：改成 barrier
                if isinstance(sr0, dict) and "km" in sr0 and "barrier" not in sr0:
                    vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
                    sr0 = dict(sr0)
                    sr0["barrier"] = {
                        "status": "PENDING",
                        "objection_source": vg.get("objection_source") or "",
                        "objection_id": vg.get("objection_id") or vg.get("barrier_id") or "",
                        "objection_name": vg.get("objection_name") or vg.get("barrier_name") or "",
                        "evidence": vg.get("objection_text") or "",
                    }
                    raw["step_result"] = sr0
                    has_full = "opening" in sr0 and "explore" in sr0 and "barrier" in sr0
            if not has_full:
                # 按 CS / 异议 / candidates 补齐五步（禁止写死 CS1D01 空壳）
                raw["step_result"] = self.default_one_click_step_result(card_state)
            else:
                # 模型给了骨架但缺文案/材料/策略：与默认合并
                defaults = self.default_one_click_step_result(card_state)
                merged = dict(defaults)
                if isinstance(sr0, dict):
                    for key in ("opening", "explore", "barrier", "info_material", "strategy"):
                        piece = sr0.get(key)
                        if isinstance(piece, dict) and piece:
                            base = dict(merged.get(key) or {})
                            for k in piece:
                                if piece.get(k) not in (None, "", [], {}):
                                    base[k] = piece.get(k)
                            merged[key] = base
                raw["step_result"] = merged
            raw["reply_type"] = "FINAL_CONFIRM"
            raw["action"] = "STAY"
            raw["mode"] = "ONE_CLICK"
            raw["card_status"] = "READY_TO_CONFIRM"
            raw["step"] = None
            # 用补齐后的 step_result 预写入 draft 再渲染，避免「推荐开场」空壳
            draft = dict(card_state)
            draft["mode"] = "ONE_CLICK"
            draft["final_status"] = "READY_TO_CONFIRM"
            draft["steps"] = dict(raw.get("step_result") or {})
            raw["reply"] = self.build_one_click_draft_reply(draft)
            raw["reason"] = str(raw.get("reason") or "ONE_CLICK")
            return raw

        # 已确认后换拜访目标（KM）：优先于确认/换开场
        if (
            str(card_state.get("target_status") or "").upper() == "CONFIRMED"
            and self.user_wants_revise_goal()
        ):
            raw["reply_type"] = "STEP"
            raw["action"] = "STAY"
            raw["step"] = None
            raw["confirm_target"] = True
            raw["card_status"] = "GENERATING"
            raw["mode"] = None
            raw["step_result"] = {}
            vg_patch = raw.get("visit_goal") if isinstance(raw.get("visit_goal"), dict) else {}
            if not vg_patch.get("km_ids"):
                found = re.findall(r"KM\d+", text.upper())
                if found:
                    vg_patch = dict(vg_patch)
                    vg_patch["km_ids"] = found
            if vg_patch:
                raw["visit_goal"] = vg_patch
            raw["reason"] = "revise_visit_goal"
            return raw

        # 用户主动「换/改」：先于确认逻辑（不依赖 user_marks_confirm）
        if self.user_wants_edit():
            sr_edit = raw.get("step_result") if isinstance(raw.get("step_result"), dict) else {}
            for mk in ("opening", "explore", "info_material", "strategy"):
                if mk in sr_edit and isinstance(sr_edit.get(mk), dict) and len(
                    [x for x in ("opening", "explore", "barrier", "info_material", "strategy") if x in sr_edit]
                ) == 1:
                    sr_edit = dict(sr_edit.get(mk) or {})
                    raw["step_result"] = sr_edit
                    break
            edit_step = str(step or card_state.get("current_step") or "").upper()
            # 话术点名要换哪一栏；笼统「换一个」跟 current_step / 上一轮 AI
            if "开场" in text:
                edit_step = "OPENING"
            elif "探寻" in text or ("题" in text and "问题" in text) or "换一道" in text or "换题" in text:
                edit_step = "EXPLORE"
            elif "策略" in text or "材料" in text:
                edit_step = "STRATEGY"
            elif edit_step not in ("OPENING", "EXPLORE", "STRATEGY", "BARRIER", "INFO_MATERIAL"):
                # READY 时 current_step 常为空：用上一轮助手话术锚定
                last_ai = ""
                try:
                    md = self.loads(self.metadata) if hasattr(self, "metadata") else {}
                    if not isinstance(md, dict):
                        md = {}
                    chats = md.get("chats") if isinstance(md.get("chats"), dict) else {}
                    last_ai = str(chats.get("last_ai_message") or "")
                except Exception:
                    last_ai = ""
                if "沟通策略" in last_ai or "确认本次拜访的沟通策略" in last_ai:
                    edit_step = "STRATEGY"
                elif "探寻" in last_ai or "确认本次拜访的探寻" in last_ai:
                    edit_step = "EXPLORE"
                elif "开场" in last_ai or "确认本次拜访的开场" in last_ai:
                    edit_step = "OPENING"
                else:
                    edit_step = "OPENING"
            if edit_step in ("BARRIER", "INFO_MATERIAL"):
                edit_step = "STRATEGY"
            # 模型没给新编号，或给了但与当前相同（等于没换）→ 脚本轮换
            same_as_current = False
            steps_now = card_state.get("steps") if isinstance(card_state.get("steps"), dict) else {}
            if edit_step == "OPENING" and sr_edit.get("opening_id"):
                cur_oid = str(((steps_now.get("opening") or {}).get("opening_id") or ""))
                if str(sr_edit.get("opening_id")) == cur_oid:
                    same_as_current = True
            elif edit_step == "EXPLORE" and (
                sr_edit.get("question_ids") or sr_edit.get("selected_ids")
            ):
                cur_q = ((steps_now.get("explore") or {}).get("question_ids") or [])
                new_q = sr_edit.get("question_ids") or sr_edit.get("selected_ids") or []
                if list(cur_q) == list(new_q):
                    same_as_current = True
            elif edit_step == "STRATEGY" and sr_edit.get("strategy_code"):
                cur_sc = str(((steps_now.get("strategy") or {}).get("strategy_code") or ""))
                if str(sr_edit.get("strategy_code")) == cur_sc:
                    same_as_current = True
            has_choice = bool(
                sr_edit
                and (
                    sr_edit.get("opening_id")
                    or sr_edit.get("question_ids")
                    or sr_edit.get("selected_ids")
                    or sr_edit.get("strategy_code")
                    or sr_edit.get("selected_pages")
                    or sr_edit.get("km_ids")
                )
            )
            if (not has_choice) or same_as_current:
                sr_edit = self.pick_alternate_step_result(card_state, edit_step, text)
                raw["step_result"] = sr_edit
            if sr_edit and (
                sr_edit.get("opening_id")
                or sr_edit.get("question_ids")
                or sr_edit.get("selected_ids")
                or sr_edit.get("strategy_code")
                or sr_edit.get("selected_pages")
                or sr_edit.get("km_ids")
            ):
                # 换栏后仍是 PENDING：等用户再说「可以」才确认，避免「换了就自动定」
                sr_edit = dict(sr_edit)
                sr_edit["status"] = "PENDING"
                raw["step_result"] = sr_edit
                raw["reply_type"] = "STEP"
                # 换完只改草稿，仍停在本步让用户再确认（不要直接 ADVANCE 跳下一步）
                raw["action"] = "STAY"
                raw["mode"] = str(card_state.get("mode") or "STEPWISE")
                raw["step"] = edit_step or step or card_state.get("current_step")
                raw["card_status"] = "READY_TO_CONFIRM" if status == "READY_TO_CONFIRM" else "GENERATING"
                raw["reason"] = "user_edit_apply_choice"
                draft = dict(card_state)
                draft["current_step"] = raw["step"]
                # 预写 steps 便于 present 读到新编号
                key = STEP_KEY.get(str(raw["step"] or "").upper())
                if key and isinstance(sr_edit, dict):
                    steps0 = dict(draft.get("steps") or {})
                    steps0[key] = dict(sr_edit)
                    draft["steps"] = steps0
                draft = self.resolve_known_step_texts(draft)
                # 换栏必须复述具体开场/探寻/策略正文；LLM 空壳「换这道」一律脚本补全文
                edit_key = STEP_KEY.get(str(raw["step"] or "").upper()) or "explore"
                item = ((draft.get("steps") or {}).get(edit_key)) or {}
                llm_reply = str(raw.get("reply") or "").strip()
                label = ""
                if edit_key == "opening":
                    label = self.opening_full_label(item)
                else:
                    label = self.step_label(edit_key, item)
                if (
                    llm_reply
                    and not self.reply_dumps_all_steps(llm_reply)
                    and self.reply_has_label(llm_reply, label)
                ):
                    raw["reply"] = llm_reply
                else:
                    raw["reply"] = self.build_edit_confirm_reply(draft, raw["step"])
                return raw
            raw["reply_type"] = "STEP"
            raw["action"] = "STAY"
            raw["mode"] = str(card_state.get("mode") or "STEPWISE")
            raw["step"] = edit_step or step or card_state.get("current_step")
            raw["step_result"] = {}
            raw["card_status"] = status or "GENERATING"
            raw["reason"] = "user_edit_await_choice"
            return raw

        if not self.user_marks_confirm():
            return raw

        # 已有完整一键产物则不覆盖；逐步误塞五步时清空
        sr = raw.get("step_result")
        if isinstance(sr, dict) and ("opening" in sr and "explore" in sr):
            if (
                self.user_wants_one_click()
                or str(card_state.get("mode") or "").upper() == "ONE_CLICK"
                or str(raw.get("mode") or "").upper() == "ONE_CLICK"
            ):
                return raw
            raw["step_result"] = {}
            sr = {}

        # 模型已给出「当前步」产物但漏 ADVANCE
        if (
            isinstance(sr, dict)
            and str(sr.get("status") or "").upper() == "CONFIRMED"
            and (
                sr.get("opening_id")
                or sr.get("selected_id")
                or sr.get("question_ids")
                or sr.get("selected_ids")
                or sr.get("strategy_code")
                or sr.get("km_ids")
            )
        ):
            cur0 = str(card_state.get("current_step") or "").upper()
            looks_opening = bool(sr.get("opening_id") or sr.get("selected_id"))
            looks_explore = bool(sr.get("question_ids") or sr.get("selected_ids"))
            looks_strategy = bool(sr.get("strategy_code"))
            matched = (
                (cur0 == "OPENING" and looks_opening and not looks_explore and not looks_strategy)
                or (cur0 == "EXPLORE" and looks_explore)
                or (cur0 == "STRATEGY" and looks_strategy)
            )
            if matched:
                raw["step"] = cur0
                if str(raw.get("action") or "").upper() != "ADVANCE":
                    raw["action"] = "ADVANCE"
                    raw["reply_type"] = "STEP"
                    raw["mode"] = "STEPWISE"
                return raw
            raw["step_result"] = {}
            sr = {}

        # 拜访目标尚未确认
        if str(card_state.get("target_status") or "").upper() != "CONFIRMED":
            raw["reply_type"] = "STEP"
            raw["action"] = "STAY"
            raw["step"] = None
            raw["card_status"] = "GENERATING"
            raw["confirm_target"] = True
            raw["step_result"] = {}
            if "00195" in text or "KM00195" in text or "关键信息" in text:
                raw["visit_goal"] = {"km_ids": ["KM00195"]}
            return raw

        # 误停在障碍/材料：自动跳过，改推策略
        if step in ("BARRIER", "INFO_MATERIAL"):
            raw["reply_type"] = "STEP"
            raw["action"] = "STAY"
            raw["step"] = "STRATEGY"
            raw["mode"] = "STEPWISE"
            raw["card_status"] = "GENERATING"
            raw["step_result"] = {}
            draft = self.auto_confirm_linked_steps(dict(card_state))
            draft["current_step"] = "STRATEGY"
            raw["reply"] = self.present_current_step_reply(draft)
            raw["reason"] = "skip_barrier_material_auto"
            return raw

        # 口语确认：强制以 card_state.current_step 为准，忽略模型乱写的 step（防开场「可以」跳到探寻/策略）
        cur = str(card_state.get("current_step") or step or "").upper()
        if cur == "OPENING" and (
            "开场" in text or "近期动态" in text or "就用" in text or "推荐" in text or self.user_marks_confirm()
        ):
            raw["reply_type"] = "STEP"
            raw["action"] = "ADVANCE"
            raw["step"] = "OPENING"
            raw["mode"] = "STEPWISE"
            raw["card_status"] = "GENERATING"
            raw["step_result"] = self.recommended_opening_confirm(card_state)
            raw["reason"] = "confirm_OPENING_only"
            return raw
        if cur == "EXPLORE" and (
            "探寻" in text or "EOS" in text or "阈值" in text or "就用" in text or "推荐" in text or self.user_marks_confirm()
        ):
            raw["reply_type"] = "STEP"
            raw["action"] = "ADVANCE"
            raw["step"] = "EXPLORE"
            raw["mode"] = "STEPWISE"
            raw["card_status"] = "GENERATING"
            raw["step_result"] = self.recommended_explore_confirm(card_state)
            raw["reason"] = "confirm_EXPLORE_only"
            return raw
        if cur == "STRATEGY" and (
            "策略" in text
            or "就用" in text
            or "推荐" in text
            or "五步" in text
            or "生成" in text
            or self.user_marks_confirm()
        ):
            raw["reply_type"] = "STEP"
            raw["action"] = "ADVANCE"
            raw["step"] = "STRATEGY"
            raw["mode"] = "STEPWISE"
            raw["card_status"] = "READY_TO_CONFIRM"
            raw["step_result"] = self.recommended_strategy_confirm(card_state)
            # 预写 steps 再渲染：强制复述已定策略名，防大模型改成缺口标签
            draft = dict(card_state)
            steps0 = dict(draft.get("steps") or {})
            steps0["strategy"] = dict(raw["step_result"] or {})
            draft["steps"] = steps0
            draft["final_status"] = "READY_TO_CONFIRM"
            draft["current_step"] = None
            raw["reply"] = self.build_strategy_ready_reply(draft)
            raw["reason"] = "confirm_STRATEGY_only"
            if self.user_confirms_final() and "确认生成" in text:
                raw["action"] = "FINISH"
                raw["reply_type"] = "DONE"
                raw["card_status"] = "CONFIRMED"
            return raw
        return raw

    def apply_one_click(self, card_state, step_result):
        if not isinstance(step_result, dict):
            raise ValueError("一键生成 step_result 必须是对象")
        # 兼容旧 km → barrier（展示步）
        if "barrier" not in step_result and isinstance(step_result.get("km"), dict):
            vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
            step_result = dict(step_result)
            step_result["barrier"] = {
                "status": "PENDING",
                "objection_source": vg.get("objection_source") or "",
                "objection_id": vg.get("objection_id") or vg.get("barrier_id") or "",
                "objection_name": vg.get("objection_name") or vg.get("barrier_name") or "",
                "evidence": vg.get("objection_text") or "",
            }
        # 缺步/空字段用 CS·异议·candidates 默认补齐
        defaults = self.default_one_click_step_result(card_state)
        for step_name in STEP_ORDER:
            key = STEP_KEY[step_name]
            raw = step_result.get(key) if isinstance(step_result.get(key), dict) else {}
            base = dict(defaults.get(key) or {})
            if isinstance(raw, dict):
                for k in raw:
                    if raw.get(k) not in (None, "", [], {}):
                        base[k] = raw.get(k)
            try:
                validated = self.validate_step_result(step_name, base)
            except ValueError:
                # 模型写了别的 CS 编码等：回退本 CS 默认
                validated = self.validate_step_result(step_name, defaults.get(key) or {})
            # 一键轮先 PENDING，整体确认后再 CONFIRMED
            validated["status"] = "PENDING"
            card_state["steps"][key] = validated
        card_state["mode"] = "ONE_CLICK"
        card_state["final_status"] = "READY_TO_CONFIRM"
        card_state["current_step"] = None
        return self.enrich_steps_for_display(card_state)

    def finish_card(self, card_state):
        # 障碍/材料始终自动补齐确认，避免 PENDING 卡死「确认生成」
        card_state = self.auto_confirm_linked_steps(card_state)
        for key in ("opening", "explore", "barrier", "info_material", "strategy"):
            item = (card_state.get("steps") or {}).get(key) or {}
            if str(item.get("status") or "").upper() != "CONFIRMED":
                # 一键整体确认：把 PENDING 全部置 CONFIRMED
                if str(card_state.get("mode") or "").upper() == "ONE_CLICK" and str(
                    item.get("status") or ""
                ).upper() == "PENDING":
                    item["status"] = "CONFIRMED"
                    card_state["steps"][key] = item
                elif key in ("barrier", "info_material"):
                    item["status"] = "CONFIRMED"
                    card_state["steps"][key] = item
                else:
                    raise ValueError("五步未全部确认，不能 FINISH：" + key)
        card_state["final_status"] = "CONFIRMED"
        card_state["current_step"] = None
        card_state["target_status"] = "CONFIRMED"
        vg = card_state.get("visit_goal")
        if isinstance(vg, dict):
            vg["status"] = "CONFIRMED"
            card_state["visit_goal"] = vg
        return card_state

    def build_final_reply(self, card_state):
        """整卡收口：五栏全文（编号已在脚本侧替换成名称/原文）。"""
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        goal_text = str(vg.get("text") or "").strip() or "已确认的拜访目标"
        return (
            "好，手卡就这么定了，可以交后端落库啦。\n"
            + "拜访目标："
            + goal_text
            + "\n"
            + self.render_five_card_blocks(card_state)
        )

    def apply_action(self, card_state, raw):
        action = str(raw.get("action") or "").upper()
        reply_type = str(raw.get("reply_type") or "").upper()
        step = raw.get("step")
        if step is not None:
            step = str(step).upper()
            if step in ("", "NULL", "NONE"):
                step = None
            # v1.9: BARRIER 为本步正式名；兼容误写 KM
            if step == "KM":
                step = "BARRIER"
        mode = raw.get("mode")
        if mode is not None:
            mode = str(mode).upper()
            if mode in ("", "NULL"):
                mode = None
        card_status = str(raw.get("card_status") or "").upper()
        step_result = raw.get("step_result") or {}
        has_step_payload = isinstance(step_result, dict) and bool(step_result)
        incoming_status = str(card_state.get("final_status") or "").upper()

        if action not in ("PRESENT_SUMMARY", "ADVANCE", "STAY", "FINISH", "FALLBACK"):
            raise ValueError("action 无效：" + action)
        if reply_type not in ("SUMMARY", "STEP", "CHITCHAT", "FINAL_CONFIRM", "DONE"):
            raise ValueError("reply_type 无效：" + reply_type)

        # 用户明确最终确认：READY_TO_CONFIRM 直接收口；策略步未落定也可先落策略再收口
        if self.user_confirms_final() and not self.user_wants_edit():
            if incoming_status == "READY_TO_CONFIRM":
                editing_step = (
                    has_step_payload
                    and mode != "ONE_CLICK"
                    and action in ("ADVANCE", "STAY")
                    and not ("opening" in step_result and "explore" in step_result)
                )
                if not editing_step:
                    return self.finish_card(card_state), None
            elif str(card_state.get("current_step") or "").upper() == "STRATEGY":
                # 策略未确认时用户直接说「确认生成」：补策略后收口
                need_strategy = True
                steps0 = card_state.get("steps") or {}
                st0 = steps0.get("strategy") if isinstance(steps0, dict) else {}
                if isinstance(st0, dict) and str(st0.get("status") or "").upper() == "CONFIRMED":
                    need_strategy = False
                if need_strategy:
                    validated = self.validate_step_result(
                        "STRATEGY",
                        {"status": "CONFIRMED", "strategy_code": "CS2D01", "custom_text": ""},
                    )
                    steps0 = dict(steps0) if isinstance(steps0, dict) else {}
                    steps0["strategy"] = validated
                    card_state["steps"] = steps0
                return self.finish_card(card_state), None

        if action == "PRESENT_SUMMARY" or reply_type == "SUMMARY":
            card_state["final_status"] = "GENERATING"
            card_state["summary"] = str(raw.get("reply") or card_state.get("summary") or "")
            if mode and mode != "ONE_CLICK":
                card_state["mode"] = mode
            # 触发轮 / 待选模式：不进 OPENING
            if str(card_state.get("target_status") or "").upper() != "CONFIRMED":
                card_state["current_step"] = None
                return card_state, None
            if self.awaiting_mode_choice(card_state) and str(mode or "").upper() != "STEPWISE":
                card_state["current_step"] = None
                card_state["mode"] = None
                return card_state, None
            # 用户已选逐步：从开场开始
            if str(card_state.get("mode") or "").upper() == "STEPWISE":
                if not card_state.get("current_step"):
                    card_state["current_step"] = "OPENING"
                return card_state, card_state.get("current_step") or "OPENING"
            if not card_state.get("current_step"):
                card_state["current_step"] = "OPENING"
            return card_state, step

        if action == "FALLBACK" or reply_type == "CHITCHAT":
            # 状态不推进；已确认 steps 原样保留
            return card_state, card_state.get("current_step")

        # 拜访目标：首次确认，或用户明确改 KM（异议字段始终只读）
        # 注意：逐步中途专精模型常误打 confirm_target=true，绝不能据此重跑定目标/清掉 STEPWISE
        want_goal = False
        if reply_type != "CHITCHAT":
            if str(card_state.get("target_status") or "").upper() != "CONFIRMED":
                if raw.get("confirm_target") or self.user_marks_confirm():
                    want_goal = True
            else:
                if self.user_wants_revise_goal():
                    want_goal = True

        if want_goal:
            card_state["target_status"] = "CONFIRMED"
            vg = card_state.get("visit_goal")
            if not isinstance(vg, dict):
                vg = {}
            patch = raw.get("visit_goal") if isinstance(raw.get("visit_goal"), dict) else {}
            if not patch and isinstance(raw.get("step_result"), dict):
                patch = raw.get("step_result").get("visit_goal") or {}
            if isinstance(patch, dict) and patch:
                for k in patch:
                    # 异议只读：忽略模型对异议字段的改写（第 3 步同理）
                    if k in (
                        "objection_id",
                        "objection_name",
                        "objection_text",
                        "barrier_id",
                        "barrier_name",
                        "barrier_evidence",
                        "objection_evidence",
                    ):
                        continue
                    vg[k] = patch[k]
            sr = raw.get("step_result") if isinstance(raw.get("step_result"), dict) else {}
            if sr.get("km_ids") and (self.user_wants_revise_goal() or not vg.get("km_ids")):
                vg["km_ids"] = sr.get("km_ids")
            gctx = self.loads(self.goal_context)
            if not isinstance(gctx, dict):
                gctx = {}
            vg = self.refresh_visit_goal_from_km(vg, gctx)
            vg["status"] = "CONFIRMED"
            card_state["visit_goal"] = vg
            card_state = self.seed_km_step_from_goal(card_state)
            # 目标确认后：写入五栏推荐草案；若本轮已点逐步/一键则直接进入
            card_state = self.seed_recommended_draft(card_state)
            card_state["final_status"] = "GENERATING"
            # 被门禁拦截的「想一键但目标未确认」不得同轮直接一键
            if str(raw.get("reason") or "") == "one_click_blocked_need_visit_goal":
                card_state["current_step"] = None
                card_state["mode"] = None
                card_state["target_status"] = "PENDING"
                if isinstance(card_state.get("visit_goal"), dict):
                    card_state["visit_goal"]["status"] = "PENDING"
                card_state["summary"] = str(raw.get("reply") or "")
                return card_state, None
            if self.user_wants_one_click():
                card_state = self.apply_one_click(
                    card_state, self.default_one_click_step_result(card_state)
                )
                return card_state, None
            if self.user_wants_stepwise():
                card_state["mode"] = "STEPWISE"
                card_state["current_step"] = "OPENING"
                card_state["summary"] = self.present_current_step_reply(card_state)
                return card_state, "OPENING"
            card_state["current_step"] = None
            card_state["mode"] = None
            card_state["summary"] = self.build_mode_choice_summary(card_state)
            return card_state, None

        if str(card_state.get("target_status") or "").upper() != "CONFIRMED":
            return card_state, None

        if mode == "ONE_CLICK" and isinstance(step_result, dict) and (
            "opening" in step_result or "explore" in step_result or "barrier" in step_result or "km" in step_result
        ):
            # 一键前确保目标已确认
            card_state["target_status"] = "CONFIRMED"
            card_state = self.apply_one_click(card_state, step_result)
            return card_state, None

        if action == "FINISH" or card_status == "CONFIRMED" or reply_type == "DONE":
            return self.finish_card(card_state), None

        # 整体草案确认话术：状态停在 READY_TO_CONFIRM，不改动已有 steps
        # 不拦截带 step_result 的 ADVANCE/STAY（逐步改某一项）
        if reply_type == "FINAL_CONFIRM" or (
            card_status == "READY_TO_CONFIRM"
            and action not in ("ADVANCE", "STAY", "FINISH")
            and not has_step_payload
        ):
            if self.count_confirmed(card_state) == 5 or self.one_click_draft_ready(card_state):
                card_state["final_status"] = "READY_TO_CONFIRM"
                if self.one_click_draft_ready(card_state):
                    card_state["mode"] = card_state.get("mode") or "ONE_CLICK"
                card_state["current_step"] = None
                return card_state, None
            # 模型声称一键/终稿但没产物：不要污染 mode
            if mode == "ONE_CLICK":
                card_state["final_status"] = card_state.get("final_status") or "GENERATING"
                return card_state, card_state.get("current_step")

        # STEPWISE
        if mode and mode != "ONE_CLICK":
            card_state["mode"] = mode
        if not card_state.get("mode"):
            card_state["mode"] = "STEPWISE"

        # 默认锁死在 card_state.current_step，防止模型 step 跳步；仅用户「换」时允许 raw.step
        working_step = card_state.get("current_step")
        if self.user_wants_edit() and step:
            working_step = step
        # READY 后改某一栏：current_step 可能为空，从 step_result 推断
        if not working_step and isinstance(step_result, dict) and step_result:
            if step_result.get("opening_id") or step_result.get("selected_id") or "opening" in step_result:
                working_step = "OPENING"
            elif step_result.get("question_ids") or step_result.get("selected_ids") or "explore" in step_result:
                working_step = "EXPLORE"
            elif step_result.get("strategy_code") or "strategy" in step_result:
                working_step = "STRATEGY"
            elif step_result.get("selected_pages") or "info_material" in step_result:
                working_step = "INFO_MATERIAL"
        if not working_step:
            working_step = step or "OPENING"
        if working_step == "KM":
            working_step = "BARRIER"
        if action in ("ADVANCE", "STAY") and isinstance(step_result, dict) and step_result:
            # 单步产物
            if "opening" in step_result or "explore" in step_result or "barrier" in step_result or "km" in step_result:
                # 若误塞了多步键且含当前步单字段，仍允许单步字段路径；多步对象走一键
                multi = 0
                for mk in ("opening", "explore", "barrier", "km", "info_material", "strategy"):
                    if mk in step_result and isinstance(step_result.get(mk), dict):
                        multi += 1
                nest_key = STEP_KEY.get(working_step)
                if multi >= 2:
                    # 逐步：模型误塞多步时只取当前步，避免整卡解析失败
                    if nest_key and isinstance(step_result.get(nest_key), dict):
                        step_result = dict(step_result.get(nest_key) or {})
                    else:
                        raise ValueError("步骤模式 step_result 只能包含单步字段")
                elif (
                    nest_key
                    and nest_key in step_result
                    and isinstance(step_result.get(nest_key), dict)
                ):
                    # 单步写成 {"opening": {...}} → 展平
                    step_result = dict(step_result.get(nest_key) or {})
            validated = self.validate_step_result(working_step, step_result)
            key = STEP_KEY[working_step]
            # 保留同一步已有字段，避免确认轮丢 note / pages
            prev = (card_state.get("steps") or {}).get(key) or {}
            if isinstance(prev, dict):
                merged = dict(prev)
                for k in validated:
                    merged[k] = validated[k]
                validated = merged
            card_state["steps"][key] = validated
            # 2.10：策略落码后立刻同步材料子选项（含 STAY 换策略）
            if working_step == "STRATEGY" and validated.get("strategy_code"):
                card_state = self.sync_materials_from_strategy(card_state, force=True)
            if action == "ADVANCE" and str(validated.get("status")).upper() == "CONFIRMED":
                # 探寻确认后：自动落障碍+材料，下一问直接策略
                if working_step == "EXPLORE":
                    card_state = self.auto_confirm_linked_steps(card_state)
                if working_step == "STRATEGY":
                    card_state = self.sync_materials_from_strategy(card_state, force=True)
                nxt = self.next_step(working_step)
                if nxt in ("BARRIER", "INFO_MATERIAL"):
                    card_state = self.auto_confirm_linked_steps(card_state)
                    nxt = "STRATEGY"
                card_state["current_step"] = nxt
                if nxt is None:
                    card_state = self.auto_confirm_linked_steps(card_state)
                    card_state["final_status"] = "READY_TO_CONFIRM"
                else:
                    card_state["final_status"] = "GENERATING"
            else:
                # READY 下改某一栏：更新后仍回整卡待确认
                if incoming_status == "READY_TO_CONFIRM" and action == "STAY":
                    if working_step == "STRATEGY":
                        card_state = self.sync_materials_from_strategy(card_state, force=True)
                    card_state = self.auto_confirm_linked_steps(card_state)
                    card_state["current_step"] = None
                    card_state["final_status"] = "READY_TO_CONFIRM"
                else:
                    card_state["current_step"] = working_step
                    card_state["final_status"] = "GENERATING"
        else:
            # 若误停在障碍/材料：自动跳过并补齐
            if str(working_step or "").upper() in ("BARRIER", "INFO_MATERIAL"):
                card_state = self.auto_confirm_linked_steps(card_state)
                working_step = "STRATEGY"
            card_state["current_step"] = working_step
            if card_status == "READY_TO_CONFIRM":
                card_state = self.auto_confirm_linked_steps(card_state)
                card_state["final_status"] = "READY_TO_CONFIRM"
            elif card_state.get("final_status") == "NOT_STARTED":
                card_state["final_status"] = "GENERATING"

        return card_state, card_state.get("current_step")

    def build_sections(self, card_state, goal_context):
        """主智能体旧 schema：sections；与 steps 双向对齐，便于 supervisor 兼容读取。"""
        steps = card_state.get("steps") or {}
        goal = goal_context or {}
        confirmed = str(card_state.get("final_status") or "").upper() == "CONFIRMED"

        def section_status(step_obj):
            st = str((step_obj or {}).get("status") or "").upper()
            if st == "CONFIRMED":
                return "CONFIRMED"
            if st == "PENDING":
                return "PENDING"
            if confirmed:
                return "CONFIRMED"
            return "NOT_STARTED"

        opening = steps.get("opening") or {}
        explore = steps.get("explore") or {}
        barrier = steps.get("barrier") or {}
        info_material = steps.get("info_material") or {}
        strategy = steps.get("strategy") or {}
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        target_ok = str(card_state.get("target_status") or "").upper() == "CONFIRMED"

        objection_id = (
            barrier.get("objection_id")
            or vg.get("objection_id")
            or goal.get("objection_id")
            or goal.get("barrier_id")
            or ""
        )
        objection_evidence = (
            barrier.get("evidence")
            or vg.get("objection_text")
            or goal.get("objection_evidence")
            or goal.get("barrier_evidence")
            or ""
        )
        objection_name = (
            barrier.get("objection_name")
            or vg.get("objection_name")
            or vg.get("barrier_name")
            or goal.get("objection_name")
            or goal.get("barrier_name")
            or ""
        )
        objection_selection = {
            "id": 0,
            "status": "CONFIRMED" if objection_id else "NOT_STARTED",
            "value": objection_id,
            "name": objection_name,
            "evidence": objection_evidence,
        }

        return {
            # 对外：异议（只读，主侧已确认）
            "objection_selection": objection_selection,
            # 兼容旧字段名
            "barrier_selection": {
                "id": 0,
                "status": objection_selection["status"],
                "value": objection_id,
                "evidence": objection_evidence,
            },
            "goal": {
                "id": 1,
                "status": "CONFIRMED" if target_ok else "PENDING",
                "value": self.visit_goal_text(card_state, goal),
            },
            "opening": {
                "id": 2,
                "status": section_status(opening),
                "value": {
                    "opening_id": opening.get("opening_id") or opening.get("selected_id") or "",
                    "direction_name": opening.get("direction_name") or "",
                    "text": opening.get("text") or "",
                },
            },
            "explore_qa": {
                "id": 3,
                "status": section_status(explore),
                "value": {
                    "question_ids": explore.get("question_ids") or explore.get("selected_ids") or [],
                    "questions": explore.get("questions") or [],
                    "note": explore.get("note") or "",
                },
            },
            # 障碍栏（只读异议）— 编号 + 名称
            "barrier_removal": {
                "id": 4,
                "status": section_status(barrier),
                "value": {
                    "objection_id": objection_id,
                    "objection_name": objection_name,
                    "objection_source": barrier.get("objection_source") or vg.get("objection_source") or "",
                    "evidence": objection_evidence,
                    "barrier_id": objection_id,
                },
            },
            # KM 来自拜访目标（编号 + 库名），勿与异议名混淆
            "km": {
                "id": 4,
                "status": "CONFIRMED" if (vg.get("km_ids") and target_ok) else section_status(barrier),
                "value": {
                    "km_ids": list(vg.get("km_ids") or []),
                    "km_items": list(vg.get("km_items") or []),
                    "km_names": list(vg.get("km_names") or []),
                    "km_texts": list(vg.get("km_texts") or []),
                    "objection_id": objection_id,
                    "objection_name": objection_name,
                },
            },
            "information_material": {
                "id": 5,
                "status": section_status(info_material),
                "value": {
                    "km_ids": info_material.get("km_ids") or list(vg.get("km_ids") or []),
                    "selected_pages": info_material.get("selected_pages") or [],
                    "material_ids": info_material.get("material_ids") or [],
                    "material_names": info_material.get("material_names") or [],
                },
            },
            "communication_strategy": {
                "id": 6,
                "status": section_status(strategy),
                "value": {
                    "strategy_code": strategy.get("strategy_code") or "",
                    "strategy_name": strategy.get("strategy_name") or "",
                    "strategy_desc": strategy.get("strategy_desc") or "",
                    "custom_text": strategy.get("custom_text") or "",
                },
            },
        }

    def empty_final_card(self):
        """主智能体契约：final_card 始终带字段壳，未确认时值为空串/空数组。"""
        return {
            "ai_cs_code": "",
            "ai_cs_name": "",
            "ai_cs_evidence": "",
            "barrier_code": "",
            "barrier_name": "",
            "barrier_evidence": "",
            "barrier_type": "",
            "goal_type": "",
            "goal_text": "",
            "opening_code": "",
            "opening_direction": "",
            "opening_text": "",
            "explore_question_code": "",
            "explore_question": "",
            "km_code": "",
            "km_text": "",
            "materials": [{"code": "", "name": "", "pages": []}],
            "strategy_code": "",
            "strategy_text": "",
            "card_summary": "",
        }

    def build_final_card(self, card_state, goal_context, confirmed):
        """始终返回字段齐全的 final_card；未确认填空，确认后写入已定内容。"""
        out = self.empty_final_card()
        if not isinstance(card_state, dict):
            return out
        g = goal_context if isinstance(goal_context, dict) else {}
        vg = card_state.get("visit_goal") if isinstance(card_state.get("visit_goal"), dict) else {}
        steps = card_state.get("steps") if isinstance(card_state.get("steps"), dict) else {}
        opening = steps.get("opening") if isinstance(steps.get("opening"), dict) else {}
        explore = steps.get("explore") if isinstance(steps.get("explore"), dict) else {}
        info_m = steps.get("info_material") if isinstance(steps.get("info_material"), dict) else {}
        strategy = steps.get("strategy") if isinstance(steps.get("strategy"), dict) else {}

        out["ai_cs_code"] = str(g.get("cs_code") or "")
        out["ai_cs_name"] = str(g.get("cs_name") or "")
        out["ai_cs_evidence"] = str(g.get("cs_evidence") or "")
        out["barrier_code"] = str(
            vg.get("objection_id")
            or vg.get("barrier_id")
            or g.get("objection_id")
            or g.get("barrier_id")
            or ""
        )
        out["barrier_name"] = str(
            vg.get("objection_name")
            or vg.get("barrier_name")
            or g.get("objection_name")
            or g.get("barrier_name")
            or ""
        )
        out["barrier_evidence"] = str(
            vg.get("objection_text")
            or vg.get("barrier_evidence")
            or g.get("objection_evidence")
            or ""
        )
        src = str(vg.get("objection_source") or g.get("objection_source") or "")
        if src.upper() in ("BARRIER", "OBJECTION"):
            out["barrier_type"] = src.upper()
        elif out["barrier_code"]:
            out["barrier_type"] = "OBJECTION" if str(out["barrier_code"]).upper().startswith("OBJ") else "BARRIER"
        out["goal_type"] = str(vg.get("goal_type") or "")
        out["goal_text"] = str(vg.get("text") or "")
        out["opening_code"] = str(opening.get("opening_id") or opening.get("selected_id") or "")
        out["opening_direction"] = str(opening.get("direction_name") or opening.get("direction_code") or "")
        out["opening_text"] = str(opening.get("text") or "")
        qids = explore.get("question_ids") or explore.get("selected_ids") or []
        if isinstance(qids, list) and qids:
            out["explore_question_code"] = str(qids[0])
        questions = explore.get("questions") or []
        if isinstance(questions, list) and questions and isinstance(questions[0], dict):
            out["explore_question"] = str(questions[0].get("text") or "")
        km_ids = vg.get("km_ids") or info_m.get("km_ids") or []
        km_names = vg.get("km_names") or vg.get("km_texts") or []
        if isinstance(km_ids, list) and km_ids:
            out["km_code"] = str(km_ids[0])
        if isinstance(km_names, list) and km_names:
            out["km_text"] = str(km_names[0])
        elif isinstance(vg.get("km_items"), list) and vg.get("km_items"):
            item0 = vg["km_items"][0]
            if isinstance(item0, dict):
                out["km_text"] = str(item0.get("km_name") or "")
        materials = []
        pages = info_m.get("selected_pages") or []
        if isinstance(pages, list):
            for page in pages:
                if not isinstance(page, dict):
                    continue
                page_no = page.get("page") or page.get("page_no") or ""
                materials.append(
                    {
                        "code": str(page.get("approval_no") or page.get("material_id") or ""),
                        "name": str(page.get("material_name") or ""),
                        "pages": [page_no] if page_no else [],
                    }
                )
        if materials:
            out["materials"] = materials
        else:
            out["materials"] = [{"code": "", "name": "", "pages": []}]
        out["strategy_code"] = str(strategy.get("strategy_code") or strategy.get("selected_id") or "")
        out["strategy_text"] = str(
            strategy.get("strategy_name") or strategy.get("strategy_desc") or strategy.get("custom_text") or ""
        )
        out["card_summary"] = str(card_state.get("summary") or "")
        # 未整卡确认也返回壳+已填进度；确认后同样结构（主侧看 card_confirmed）
        return out

    def build_card_payload(self, card_state, goal_context):
        steps = card_state.get("steps") or {}
        g = goal_context or {}
        objection_id = g.get("objection_id") or g.get("barrier_id") or ""
        objection_name = g.get("objection_name") or g.get("barrier_name") or ""
        objection_evidence = g.get("objection_evidence") or g.get("barrier_evidence") or ""
        return {
            "final_status": card_state.get("final_status"),
            "mode": card_state.get("mode"),
            "current_step": card_state.get("current_step"),
            "target_status": card_state.get("target_status"),
            "visit_goal": card_state.get("visit_goal") or {},
            "summary": card_state.get("summary") or "",
            "cs_code": g.get("cs_code") or "",
            # 对外：异议；barrier_* 仅兼容
            "objection_id": objection_id,
            "objection_name": objection_name,
            "objection_evidence": objection_evidence,
            "barrier_id": objection_id,
            "barrier_name": objection_name,
            "barrier_evidence": objection_evidence,
            "opening": steps.get("opening") or {},
            "explore": steps.get("explore") or {},
            "barrier": steps.get("barrier") or {},
            # 兼容旧读取方
            "km": {
                "status": (steps.get("barrier") or {}).get("status"),
                "km_ids": (card_state.get("visit_goal") or {}).get("km_ids") or [],
                "km_items": (card_state.get("visit_goal") or {}).get("km_items") or [],
                "note": "",
            },
            "info_material": steps.get("info_material") or {},
            "strategy": steps.get("strategy") or {},
            "progress": {
                "done": self.count_confirmed(card_state),
                "total": 5,
            },
        }

    def is_chitchat_turn(self, reply_type, action=None, reason=None):
        """LLM 判闲聊：意图识别 CHITCHAT / 专精 reply_type / FALLBACK / 跑题关键词。"""
        if str(reply_type or "").upper() == "CHITCHAT":
            return True
        if str(action or "").upper() == "FALLBACK":
            return True
        if str(self.intent or "").upper() == "CHITCHAT":
            return True
        reason_text = str(reason or "").lower()
        if "chitchat" in reason_text or "offtopic" in reason_text or "guide_back" in reason_text:
            return True
        if self.looks_like_offtopic():
            return True
        return False

    def merge_metadata(self, card_state, reply_type, step, progress, goal_context, action=None, reason=None):
        metadata = self.loads(self.metadata)
        if not isinstance(metadata, dict):
            metadata = {}
        state = metadata.get("state")
        if not isinstance(state, dict):
            state = {}

        sections = self.build_sections(card_state, goal_context)
        # 主智能体读取的完成标记：final_status == CONFIRMED（同时 job 可由主侧置 COMPLETED）
        card_out = dict(card_state)
        card_out["sections"] = sections
        card_out["current_id"] = card_state.get("current_id")
        if card_out.get("current_id") is None:
            card_out["current_id"] = 0

        state["card_state"] = card_out
        state["stage"] = "CARD"
        job = state.get("job")
        if not isinstance(job, dict):
            job = {}
        # 无关问题：LLM 判闲聊时 unrelated_count +1；不清零、不因满 N 退出
        try:
            unrelated = int(job.get("unrelated_count") or 0)
        except (TypeError, ValueError):
            unrelated = 0
        if self.is_chitchat_turn(reply_type, action=action, reason=reason):
            unrelated = unrelated + 1
        job["unrelated_count"] = unrelated
        if str(card_out.get("final_status") or "").upper() == "CONFIRMED":
            job["status"] = "COMPLETED"
        elif not job.get("status"):
            job["status"] = "ACTIVE"
        state["job"] = job

        metadata["state"] = state
        metadata["card_state"] = card_out
        metadata["reply_type"] = reply_type
        metadata["step"] = step
        metadata["progress"] = progress
        card_payload = self.build_card_payload(card_out, goal_context)
        metadata["card"] = card_payload
        # 明确完成标记（主智能体也可只看 final_status）
        confirmed = str(card_out.get("final_status") or "").upper() == "CONFIRMED"
        metadata["card_confirmed"] = confirmed
        # final_card：始终输出字段壳（空串）；确认后写入已定内容。禁止中间轮 null。
        final_card = self.build_final_card(card_out, goal_context, confirmed)
        metadata["final_card"] = final_card
        state["final_card"] = final_card
        # 兼容主智能体旧 final_status 词汇：GENERATING/READY_TO_CONFIRM → PENDING
        if card_out.get("final_status") in ("READY_TO_CONFIRM", "GENERATING"):
            metadata["card_legacy_status"] = "PENDING"
        else:
            metadata["card_legacy_status"] = card_out.get("final_status")
        metadata["unrelated_count"] = unrelated
        metadata["card_aborted"] = False
        metadata["exit_reason"] = ""
        return metadata

    def result(self):
        try:
            card_state = self.loads(self.card_state)
            if not isinstance(card_state, dict):
                card_state = {}
            self.candidates = self.loads(self.candidates)
            if not isinstance(self.candidates, dict):
                self.candidates = {}
            goal_context = self.loads(self.goal_context)
            if not isinstance(goal_context, dict):
                goal_context = {}

            raw = self.parse_llm(self.llm_raw)
            # 用户明显跑题：强制 CHITCHAT；优先保留闲聊专精 LLM 的 reply
            if self.looks_like_offtopic():
                llm_reply = str(raw.get("reply") or "").strip()
                raw["reply_type"] = "CHITCHAT"
                raw["action"] = "FALLBACK"
                raw["step_result"] = {}
                raw["card_status"] = card_state.get("final_status") or "GENERATING"
                if self.keep_specialist_reply(llm_reply):
                    raw["reply"] = llm_reply
                else:
                    raw["reply"] = "这个我只能简单接一下～ " + self.guide_back_hint(card_state)
                raw["reason"] = "chitchat_guide_back"
            else:
                raw = self.coerce_raw_from_user(card_state, raw)

            reply = str(raw.get("reply") or "").strip()
            if not reply:
                raise ValueError("reply 为空")

            card_state, current_step = self.apply_action(card_state, raw)
            # 持久化：编号 → 全文写回 steps（下一轮 card_state 可读；reply 另算）
            if str(card_state.get("mode") or "").upper() == "ONE_CLICK" or str(
                card_state.get("final_status") or ""
            ).upper() in ("READY_TO_CONFIRM", "CONFIRMED"):
                card_state = self.enrich_steps_for_display(card_state)
            else:
                card_state = self.resolve_known_step_texts(card_state)

            done = self.count_confirmed(card_state)
            progress = {"done": done, "total": 5}
            # 以脚本复核为准
            model_progress = raw.get("progress") or {}
            if isinstance(model_progress, dict):
                # 忽略模型 done，保留 total 容错
                progress["total"] = int(model_progress.get("total") or 5)

            reply_type = str(raw.get("reply_type") or "").upper()
            action = str(raw.get("action") or "").upper()
            step = raw.get("step")
            if step is not None:
                step = str(step).upper()
                if step in ("", "NULL", "NONE"):
                    step = None
            if step is None and reply_type not in ("SUMMARY", "DONE", "FINAL_CONFIRM"):
                step = current_step

            # 收口后对外统一标记；覆盖模型误写的「确认拜访目标」话术
            if str(card_state.get("final_status") or "").upper() == "CONFIRMED":
                reply_type = "DONE"
                action = "FINISH"
                reply = self.build_final_reply(card_state)
                if not str(raw.get("reason") or "").strip() or "拜访目标" in str(raw.get("reason") or ""):
                    raw["reason"] = "整卡确认生成 → final_card"
            else:
                # 一键草案：enrich 后强制用脚本渲染五栏全文（修空壳「推荐开场」）
                # 目标未确认 / 门禁拦截时禁止盖成一键汇总
                if (
                    str(card_state.get("target_status") or "").upper() == "CONFIRMED"
                    and str(card_state.get("mode") or "").upper() == "ONE_CLICK"
                    and str(card_state.get("final_status") or "").upper() == "READY_TO_CONFIRM"
                    and reply_type in ("FINAL_CONFIRM", "SUMMARY", "STEP", "")
                    and not self.user_wants_edit()
                    and str(raw.get("reason") or "") != "one_click_blocked_need_visit_goal"
                ):
                    reply = self.build_one_click_draft_reply(card_state)
                    reply_type = "FINAL_CONFIRM"
                else:
                    # 一键/逐步：状态对了但 reply 串台时人性化改写（给人看的话术）
                    reply = self.humanize_reply(card_state, reply, reply_type)
                # 逐步 ADVANCE 后：一律只讲新的 current_step，避免模型把五栏一起念完
                if (
                    str(card_state.get("mode") or "").upper() == "STEPWISE"
                    and str(action or "").upper() == "ADVANCE"
                    and str(card_state.get("final_status") or "").upper()
                    not in ("READY_TO_CONFIRM", "CONFIRMED")
                ):
                    reply = self.present_current_step_reply(card_state)
                    reply_type = "STEP"

            metadata = self.merge_metadata(
                card_state,
                reply_type,
                step,
                progress,
                goal_context,
                action=action,
                reason=raw.get("reason"),
            )
            return {
                "parse_ok": True,
                "error": "",
                "reply": reply,
                "reply_type": reply_type,
                "action": action,
                "step": step,
                "progress": progress,
                "mode": card_state.get("mode"),
                "card_status": card_state.get("final_status"),
                "card_state": card_state,
                "card": metadata.get("card"),
                "final_card": metadata.get("final_card"),
                "state": metadata.get("state") or {"card_state": card_state},
                "metadata": metadata,
                "card_confirmed": metadata.get("card_confirmed"),
                "card_legacy_status": metadata.get("card_legacy_status"),
                "card_aborted": False,
                "unrelated_count": metadata.get("unrelated_count"),
                "reason": str(raw.get("reason") or ""),
            }
        except (ValueError, TypeError, KeyError, AttributeError) as error:
            card_state = self.loads(self.card_state)
            if not isinstance(card_state, dict):
                card_state = {}
            goal_context = self.loads(self.goal_context)
            if not isinstance(goal_context, dict):
                goal_context = {}
            # 模型 JSON 坏了时：若用户明确确认，用 coerce 兜底推进，避免卡死
            try:
                raw = {
                    "reply": "",
                    "reply_type": "STEP",
                    "action": "STAY",
                    "step": card_state.get("current_step"),
                    "step_result": {},
                    "mode": card_state.get("mode") or "STEPWISE",
                    "card_status": card_state.get("final_status") or "GENERATING",
                    "reason": "parse_error_recover",
                }
                if self.looks_like_offtopic():
                    raw["reply_type"] = "CHITCHAT"
                    raw["action"] = "FALLBACK"
                    if not self.keep_specialist_reply(raw.get("reply")):
                        raw["reply"] = "这个我只能简单接一下～ " + self.guide_back_hint(card_state)
                else:
                    raw = self.coerce_raw_from_user(card_state, raw)
                    if not str(raw.get("reply") or "").strip():
                        raw["reply"] = "好，按您刚才说的继续。"
                if self.user_marks_confirm() or self.user_confirms_final() or self.looks_like_offtopic():
                    card_state, current_step = self.apply_action(card_state, raw)
                    reply_type = str(raw.get("reply_type") or "STEP").upper()
                    action = str(raw.get("action") or "STAY").upper()
                    recover_reply = str(raw.get("reply") or "")
                    if str(card_state.get("final_status") or "").upper() == "CONFIRMED":
                        reply_type = "DONE"
                        action = "FINISH"
                        recover_reply = self.build_final_reply(card_state)
                    elif reply_type == "CHITCHAT":
                        if not self.keep_specialist_reply(recover_reply):
                            recover_reply = "这个我只能简单接一下～ " + self.guide_back_hint(card_state)
                    elif str(card_state.get("final_status") or "").upper() == "READY_TO_CONFIRM":
                        recover_reply = self.build_one_click_draft_reply(card_state)
                    elif str(card_state.get("mode") or "").upper() == "STEPWISE":
                        recover_reply = self.present_current_step_reply(card_state)
                        reply_type = "STEP"
                    elif not recover_reply:
                        recover_reply = "好，按您刚才说的继续。"
                    progress = {"done": self.count_confirmed(card_state), "total": 5}
                    metadata = self.merge_metadata(
                        card_state,
                        reply_type,
                        current_step,
                        progress,
                        goal_context,
                        action=action,
                        reason=raw.get("reason"),
                    )
                    return {
                        "parse_ok": False,
                        "error": str(error),
                        "reply": recover_reply,
                        "reply_type": reply_type,
                        "action": action,
                        "step": current_step,
                        "progress": progress,
                        "mode": card_state.get("mode"),
                        "card_status": card_state.get("final_status"),
                        "card_state": card_state,
                        "card": metadata.get("card"),
                        "final_card": metadata.get("final_card"),
                        "state": metadata.get("state") or {"card_state": card_state},
                        "metadata": metadata,
                        "card_confirmed": metadata.get("card_confirmed"),
                        "card_legacy_status": metadata.get("card_legacy_status"),
                        "reason": "parse_error_recovered",
                    }
            except (ValueError, TypeError, KeyError, AttributeError):
                pass
            progress = {"done": self.count_confirmed(card_state), "total": 5}
            metadata = self.merge_metadata(
                card_state,
                "STEP",
                card_state.get("current_step"),
                progress,
                goal_context,
            )
            return {
                "parse_ok": False,
                "error": str(error),
                "reply": "手卡结果解析失败，请再试一次，或换一种确认方式。",
                "reply_type": "STEP",
                "action": "FALLBACK",
                "step": card_state.get("current_step"),
                "progress": progress,
                "mode": card_state.get("mode"),
                "card_status": card_state.get("final_status"),
                "card_state": card_state,
                "card": metadata.get("card"),
                "state": metadata.get("state") or {"card_state": card_state},
                "metadata": metadata,
                "card_confirmed": metadata.get("card_confirmed"),
                "card_legacy_status": metadata.get("card_legacy_status"),
                "reason": "parse_error",
            }


def execute_card_llm_result(params):
    return CardResultFormatter(params).result()
